INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4968', 'spa', 'Matusalén — patriarca antediluviano, hijo de Enoc, abuelo de Noé; la persona más longeva registrada en las Escrituras (969 años).', 'Nombre propio del célebre patriarca antediluviano perteneciente a la línea de Set, hijo de Enoc y abuelo de Noé. Matusalén vivió 969 años, lo que lo convierte en el individuo más longevo registrado en las Escrituras (Gn 5:27). Su nombre podría significar ''hombre del dardo'' o derivar de una fuente babilónica. Las seis apariciones del nombre se concentran en la genealogía de Génesis 5:21-27, con un paralelo en 1 Crónicas 1:3. La Septuaginta lo transcribe como Μαθουσαλα, y las tradiciones occidentales preservan transliteraciones similares, reflejando la amplia familiaridad con esta figura emblemática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4970', 'spa', 'Cuando? -- adverbio interrogativo de tiempo, frecuente en el clamor urgente ''hasta cuando?'' (ad-matay)', 'Cuando? -- adverbio interrogativo de tiempo, frecuente en el clamor urgente ''hasta cuando?'' (ad-matay)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4971', 'spa', 'medida, cantidad fija, proporcion; cuota de productos; composicion o norma establecida', 'Sustantivo femenino que denota una medida fija, proporcion o cuota. En Exodo 5:8 especifica la cantidad requerida de ladrillos que Israel debia producir, una cuota diaria bajo la opresion del faraon. Los pasajes de Exodo 30 lo aplican a la composicion exacta del aceite sagrado de la uncion, que no debia replicarse. Ezequiel 45:11 lo emplea para la proporcion estandarizada entre el efa y el bato. El espanol ''proporcion'' refleja fielmente el sentido de estandarizacion.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4973', 'spa', 'Colmillos o muelas, especialmente incisivos o dientes de fieras, con énfasis en su carácter agresivo', 'Este término hebraico tardío designa los dientes, particularmente los dientes frontales prominentes o colmillos. Siempre aparece en paralelo con la palabra más común para ''dientes'' (שִׁנַּיִם). Job lo usa al describir cómo ''quebraba los colmillos del injusto'' y le arrebataba la presa de los dientes. Proverbios advierte sobre una generación ''cuyos dientes son espadas, cuyos colmillos son cuchillos'', retratando violencia y opresión. Joel describe al ejército de langostas con ''colmillos de león'', resaltando su poder destructor. El término subraya el aspecto agresivo y peligroso de la dentadura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4974', 'spa', 'מְתֹם — sanidad, integridad, plenitud (física o moral)', 'Este sustantivo denota sanidad, integridad o plenitud: el estado de estar intacto y sin daño. El término aparece exclusivamente en construcciones negativas (''no hay sanidad''), describiendo heridas físicas o destrucción total. En Isaías y Salmos, retrata cuerpos devastados por la enfermedad o las heridas sin que quede un solo lugar sano. En Jueces, puede describir la destrucción urbana completa. El concepto enfatiza la totalidad: o bien salud completa o bien devastación absoluta, sin término medio posible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4975', 'spa', 'Lomos, cintura -- la region lumbar y de las caderas; por extension, sede del poder procreativo y del linaje', 'Lomos, cintura -- la region lumbar y de las caderas; por extension, sede del poder procreativo y del linaje');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4976', 'spa', 'regalo, presente, dadiva; dote matrimonial; ofrenda entregada a los sacerdotes', 'Sustantivo masculino colectivo que designa regalos o presentes, abarcando contextos sociales, matrimoniales y sagrados. En Genesis 34:12, Siquem ofrece pagar cualquier dote que se le exija junto con el precio de la novia, mostrando su uso en negociaciones matrimoniales. Numeros 18:11 lo aplica a las ofrendas mecidas entregadas a los sacerdotes. Proverbios lo emplea para las dadivas que facilitan las relaciones (18:16; 21:14) o atraen amigos (19:6). Los terminos espanoles ''regalo'' y ''dadiva'' captan en conjunto tanto la dimension personal como la transaccional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4977', 'spa', 'Matán, nombre propio que significa ''don'' o ''regalo'', llevado por un sacerdote de Baal y un padre judío', 'Este nombre aparece asociado a dos individuos distintos en la Biblia hebrea. Un Matán fue sacerdote de Baal en Jerusalén durante el reinado de la reina Atalía, y fue ejecutado cuando Joyadá lideró la contrarrevolución y destruyó el templo de Baal (2 Re 11; 2 Cr 23). El otro fue padre de Sefatías, uno de los oficiales que se opusieron a Jeremías y lo arrojaron a una cisterna (Jer 38). El nombre significa ''don'' o ''regalo'', de la misma raíz que la palabra común para ''regalo'' (מַתָּן).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4978', 'spa', 'Dones, recompensas o presentes otorgados en honor o compensación por un rey', 'Este préstamo arameo aparece únicamente en Daniel y designa los dones o recompensas que un rey concede. En dos ocasiones, Nabucodonosor promete «dones» junto con recompensas y honores a quien logre interpretar sus sueños. Cuando Daniel interpreta el sueño, le ofrecen estos presentes, pero él los rechaza inicialmente diciendo: «Quédense tus dones para ti.» El término subraya la generosidad regia: los valiosos obsequios que un monarca otorga a quienes le sirven bien o logran hazañas difíciles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4979', 'spa', 'Don, ofrenda o presente; desde donaciones voluntarias a Dios hasta sobornos que corrompen el juicio. מַתָּנָה abarca todo el espectro moral del dar. E', 'Don, ofrenda o presente; desde donaciones voluntarias a Dios hasta sobornos que corrompen el juicio. מַתָּנָה abarca todo el espectro moral del dar. En su mejor expresión, describe ofrendas voluntarias consagradas a Dios (Éx 28:38, Lv 23:38, Nm 18:29) o regalos generosos entre personas, como cuando Abraham dio regalos a los hijos de sus concubinas (Gn 25:6). Deuteronomio 16:17 vincula el dar con la capacidad: ''cada uno según el don de su mano.'' No obstante, la misma palabra se oscurece en Proverbios 15:27 y Eclesiastés 7:7, donde el ''don'' se convierte en soborno que corrompe el corazón. El español distingue nítidamente entre ''don/ofrenda'' y ''soborno,'' revelando la polaridad moral que el hebreo deja implícita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4982', 'spa', 'Matenai, nombre personal abreviado que significa «don de Yahvé»', 'Este nombre teofórico abreviado designa a tres hombres distintos de la comunidad postexílica. Dos de ellos figuran entre quienes se habían casado con mujeres extranjeras y se divorciaron durante las reformas de Esdras: uno en Esdras 10:33 y otro en 10:37. El tercero es un sacerdote mencionado en Nehemías 12:19. El nombre es una forma abreviada de Matanías («don de Yahvé»), que suprime el elemento divino para crear una forma más breve. Las versiones de la LXX muestran variaciones (Ματθαναι, Μαθθαναι) pero conservan la estructura consonántica básica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4983', 'spa', 'Matanías: nombre propio que significa ''don de YHWH,'' llevado por cantores levíticos, un rey y figuras postexílicas. Nombre teofórico compuesto de מַתָ', 'Matanías: nombre propio que significa ''don de YHWH,'' llevado por cantores levíticos, un rey y figuras postexílicas. Nombre teofórico compuesto de מַתָּנָה (''don'') y Yah, que significa ''don del SEÑOR.'' Su portador políticamente más significativo es el último rey de Judá, cuyo nombre Nabucodonosor cambió a Sedequías (2 R 24:17). El nombre aparece con mayor frecuencia entre músicos levíticos descendientes de Asaf y Hemán (1 Cr 25:4, 16; 2 Cr 29:13; Neh 11:17, 22; 12:8, 25, 35). Varios laicos postexílicos que se habían casado con mujeres extranjeras también llevaron este nombre (Esd 10:26, 27, 30, 37).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4985', 'spa', 'endulzarse, volverse dulce o agradable; saber dulce; figuradamente, ser deleitoso o placentero', 'Verbo que significa volverse dulce o ser agradable, abarcando tanto el sabor literal como el deleite figurado. En Exodo 15:25 las aguas amargas de Mara se endulzan cuando Dios muestra a Moises un arbol para echar en ellas, un relato vivido de transformacion divina. Proverbios 9:17 advierte que las aguas robadas ''saben dulces'', usando la dulzura literal como metafora del atractivo del placer ilicito. Job emplea la palabra para la agradable sensacion que los impios encuentran aun en la muerte (21:33) y la dulzura del mal bajo la lengua (20:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4991', 'spa', 'Don, regalo, dádiva — algo otorgado generosamente, ya sea una bendición divina, una recompensa humana o una ofrenda prometida.', 'Sustantivo femenino que designa un don, regalo o dádiva, y aparece tanto en forma constructa como absoluta. Abarca diversos contextos de donación: una recompensa real ofrecida a un profeta (1 R 13:7), lo que la mano de cada uno pueda dar como ofrenda voluntaria (Ez 46:5, 11), el don de Dios que permite al ser humano disfrutar de las bendiciones de la vida (Ec 3:13; 5:19), y un regalo engañoso que se promete pero nunca se entrega (Pr 25:14). La expresión constructa ''don de su mano'' en Ezequiel capta hermosamente la idea de dar conforme a las posibilidades de cada uno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4993', 'spa', 'Matatías: nombre teofórico que significa ''don de YHWH'', portado por varios levitas y otros personajes bíblicos', 'Nombre propio hebreo compuesto de מַתָּן (''don, regalo'') y יָהוּ (forma abreviada de YHWH), con el significado de ''don del Señor''. Presenta dos variantes ortográficas: la forma larga מַתִּתְיָהוּ y la corta מַתִּתְיָה. Lo llevan al menos cuatro individuos: un músico levita designado por David para la procesión del arca (1 Cr 15:18, 21; 16:5; 25:3, 21), un levita encargado de las ofrendas horneadas (1 Cr 9:31), un asistente de Esdras en la lectura pública de la Torá (Neh 8:4) y un hombre que había tomado esposa extranjera (Esd 10:43). La forma griega posterior Ματταθίας se hizo célebre por el patriarca macabeo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4994', 'spa', 'Por favor, te ruego; partícula enclítica de súplica, exhortación o atenuación retórica', 'נָא es una partícula diminuta pero notablemente expresiva que suaviza órdenes convirtiéndolas en peticiones, transformando imperativos en apelaciones. Adherida a verbos en el habla coloquial, aparece más de 400 veces, lo que la convierte en uno de los marcadores discursivos más frecuentes del hebreo. Abraham la usa al pedir a Sara que diga que es su hermana (Gn 12:13), Moisés al suplicar a Dios (Éx 32:31) y Dios mismo al desafiar a Job (Job 40:10). Su fuerza va desde la cortesía amable hasta la urgencia desesperada, y los traductores luchan con ella: ''por favor'', ''te ruego'', ''te suplico'' solo captan una fracción de su alcance pragmático.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4996', 'spa', 'No (Tebas), la gran ciudad egipcia sobre el Nilo, sede del dios Amón', 'No es la designación hebrea de Tebas, la espléndida capital del Alto Egipto situada a orillas del Nilo, unos 640 kilómetros al sur del Delta. Nahúm 3:8 la llama No-Amón (''No de Amón''), vinculándola con su deidad tutelar, y desafía a Nínive comparando su caída inminente con la destrucción de Tebas. Jeremías 46:25 anuncia el juicio divino sobre ''Amón de No'', mientras Ezequiel 30:14-16 enumera a No junto con otras fortalezas egipcias destinadas a la devastación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4997', 'spa', 'Odre, pellejo — recipiente de cuero para transportar líquidos como vino o leche.', 'Sustantivo masculino que designa un odre o pellejo, un recipiente de cuero utilizado para almacenar y transportar líquidos. Aparece en contextos narrativos y poéticos memorables: los odres gastados de la engañosa embajada gabaonita ante Josué (Jos 9:4, 13), el odre de leche que Jael abrió para Sísara (Jue 4:19), el odre de vino que Isaí envió con David a Saúl (1 S 16:20), y dos vívidas imágenes sálmicas: Dios recogiendo las lágrimas en un odre (Sal 56:8) y el salmista sintiéndose como odre reseco al humo (Sal 119:83). El término español ''odre'' desciende del latín uter, conservando este antiguo concepto mediterráneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4998', 'spa', 'Ser hermoso, agraciado o apropiado; convenir o ser adecuado', 'Este verbo poco frecuente aparece en contextos de belleza y conveniencia. El Cantar de los Cantares lo emplea para elogiar la hermosura de la amada: «Hermosas son tus mejillas.» Isaías lo utiliza para los bellos pies del mensajero que trae buenas nuevas. Y el Salmo 93 declara que «la santidad conviene a tu casa, oh SEÑOR.» La raíz conecta la belleza estética con la idoneidad moral: lo que es hermoso a la vista y lo que resulta adecuado o propio en su contexto, tendiendo un puente entre la apariencia externa y la conveniencia interna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H4999', 'spa', 'Pastos, praderas — terreno abierto de pastoreo donde pacen los rebaños; figura de provisión divina o de desolación', 'El sustantivo נָאוָה (navah II) designa pastos o praderas: terreno abierto y bien regado para el pastoreo. Su aparición más entrañable es Salmo 23:2, donde el SEÑOR hace reposar al salmista en «verdes pastos». Los pastos del desierto destilan abundancia en Salmo 65:12, mientras que Joel 1:19-20 lamenta su destrucción por el fuego. La palabra lleva carga teológica: pastos florecientes señalan bendición; pastos desolados marcan juicio (Jer 9:10). El Salmo 83:12 recoge a enemigos que pretendían apoderarse de «los pastos de Dios».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5000', 'spa', 'Hermoso, bello; o apropiado, decoroso — referido tanto a la belleza física como a la conveniencia moral', 'Un adjetivo con dos registros de significado bien diferenciados. En el Cantar de los Cantares y en Jeremías 6:2 describe belleza física: la amada es «morena pero hermosa» (Cnt 1:5), su rostro es bello (2:14) y Jerusalén se compara con una mujer delicada y hermosa. En los Salmos y Proverbios se desplaza hacia lo moralmente apropiado: la alabanza es «decorosa» para los rectos (Sal 33:1; 147:1), mientras que el lujo «no conviene» al necio (Pr 19:10). La evidencia multilingüe refleja esta división con nitidez: las glosas del Cantar se agrupan en torno a ''bella/hermosa'', mientras que los textos sapienciales emplean ''apropiado/conveniente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5002', 'spa', 'Oráculo, declaración profética; fórmula solemne que marca el discurso como divinamente autorizado', 'Neʾum es la fórmula de citación profética por excelencia, que aparece 376 veces casi exclusivamente en la expresión neʾum YHWH (''declara el SEÑOR''). Enmarca el discurso profético como palabra divina directa, distinguiéndolo del habla humana ordinaria. Fuera de esta fórmula, introduce los oráculos extáticos de Balaam (Nm 24:3, 15) y las últimas palabras de David (2 S 23:1). Su forma exclusivamente en estado constructo y su posición sintáctica fija le confieren una cualidad formulaica, casi litúrgica, que señala al oyente: lo que sigue no es opinión del profeta, sino declaración de Dios mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5003', 'spa', 'Cometer adulterio, literalmente de union sexual ilicita y figuradamente de infidelidad idolatrica hacia Dios', 'Cometer adulterio, literalmente de union sexual ilicita y figuradamente de infidelidad idolatrica hacia Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5006', 'spa', 'Despreciar, desdeñar o mostrar menosprecio; en Piel, blasfemar o injuriar; raramente, florecer (raíz homógrafa)', 'Despreciar, desdeñar o mostrar menosprecio; en Piel, blasfemar o injuriar; raramente, florecer (raíz homógrafa)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5007b', 'spa', 'Blasfemias, actos o palabras de desprecio dirigidos contra Dios que expresan escarnio e insulto', 'Este sustantivo femenino plural designa actos de blasfemia o desprecio dirigidos específicamente contra el SEÑOR. En Nehemías 9:18, 26, describe las grandes provocaciones de Israel durante la peregrinación por el desierto y el período de los jueces: fabricar un becerro de oro y cometer «grandes blasfemias». Ezequiel 35:12 lo aplica a Edom (monte Seir), cuyas burlas contra los montes de Israel fueron oídas por Dios y serán juzgadas. El término conlleva no solo insulto verbal, sino la noción de un rechazo deliberado y despectivo. La raíz נאץ significa despreciar o tratar con menosprecio, y la forma plural enfatiza actos reiterados de tal desafío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5009', 'spa', 'נְאָקָה — gemido, suspiro de los oprimidos o heridos', 'Este sustantivo femenino denota gemido o suspiro: la expresión audible del sufrimiento, la opresión o la angustia. El término aparece en contextos de aflicción severa: la esclavitud de Israel en Egipto, su sufrimiento bajo los jueces y el lamento de un guerrero mortalmente herido. Significativamente, se usa para describir el clamor que mueve a Dios a actuar: Él escucha el gemido de su pueblo oprimido y responde con liberación. La palabra capta el grito inarticulado del sufrimiento que precede a la oración formulada, el gemido que surge de circunstancias insoportables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5011', 'spa', 'Nob — ciudad sacerdotal en Benjamín cerca de Jerusalén, lugar de la huida de David a Ahimelec y la posterior masacre.', 'Nombre propio que designa a Nob, una ciudad sacerdotal en el territorio de Benjamín, ubicada cerca de Jerusalén. Es célebre como el lugar donde David huyó ante Ahimelec el sacerdote, recibió los panes de la proposición y la espada de Goliat (1 S 21:1-9), y cuyos sacerdotes Saúl masacró como represalia (1 S 22:9-19). Isaías 10:32 la sitúa en la ruta de un avance asirio hacia Jerusalén, y Nehemías 11:32 la enumera entre los asentamientos benjaminitas repoblados tras el exilio. La ubicación exacta sigue debatiéndose, aunque la mayoría de los estudiosos la ubican en la cresta del Monte de los Olivos, con vista directa a Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5012', 'spa', 'Profetizar: proclamar la palabra de Dios con autoridad divina (Nifal) o profetizar extáticamente bajo impulso del Espíritu (Hitpael)', 'Navaʾ es el verbo hebreo para la actividad profética en sus dimensiones tanto deliberada como extática. El Nifal expresa el sentido habitual de pronunciar un oráculo o mensaje divino bajo la autoridad de Dios — la proclamación profética de Jeremías, Ezequiel y los profetas clásicos. El Hitpael conserva la connotación más antigua y visceral de ser arrebatado por el impulso profético, frecuentemente con comportamiento extático, como cuando Saúl cae entre los profetas (1 S 10:10-13) o los setenta ancianos profetizan junto a la tienda del encuentro (Nm 11:25-27). El español emplea uniformemente ''profetizar'', aunque este término moderno aplana la vívida distinción entre la proclamación oracular autorizada y la experiencia extática bajo la acción del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5014', 'spa', 'נָבוּב — hueco, ahuecado; vacío o vacante (en sentido literal o figurado)', 'Este adjetivo significa hueco o ahuecado, y describe algo con espacio vacío en su interior en lugar de ser sólido. Aparece en las instrucciones técnicas de construcción del tabernáculo y del templo, donde el altar de bronce debía fabricarse hueco con tablas, así como en la descripción de las columnas del templo de Salomón. En sentido figurado, Job 11:12 lo emplea para referirse a una persona vacía de entendimiento, comparándola con un asno montés. La imagen básica proviene de objetos huecos como cañas o flautas, evocando un interior excavado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5015a', 'spa', 'Nebo — ciudad moabita al este del Jordán y monte desde el cual Moisés contempló la Tierra Prometida', 'Nebo (נְבוֹ) es un topónimo que designa tanto una ciudad de Moab como la cumbre montañosa desde la cual Moisés contempló la Tierra Prometida. Como ciudad, fue asignada a la tribu de Rubén, que la reconstruyó (Nm 32:3, 38). Como monte, Dios ordena a Moisés: «Sube al monte Nebo» (Dt 32:49), y desde su cima contempla la tierra antes de morir (Dt 34:1). Los israelitas acamparon cerca de él durante la travesía del desierto (Nm 33:47). Isaías y Jeremías mencionan la ciudad en oráculos contra Moab (Is 15:2; Jer 48:1, 22). Todos los idiomas principales lo transliteran directamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5016', 'spa', 'Profecía, ya sea revelación divina genuina o pretensión profética falsa', 'Este término hebreo tardío para profecía aparece en Crónicas y Nehemías, y distingue los oráculos proféticos escritos del sinónimo más antiguo «visión» (חָזוֹן). Puede referirse a una profecía auténtica, como la de Ahías silonita (2 Cr 9), o a un genuino aliento profético (2 Cr 15). Sin embargo, Nehemías lo emplea para una profecía falsa contratada para intimidarlo. El término subraya la naturaleza verbal y textual del oráculo profético: la profecía como mensaje, ya sea verdadero o fraudulento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5018', 'spa', 'Nebuzaradán: capitán de la guardia babilónico que supervisó la destrucción de Jerusalén y la deportación de Judá. El nombre acadio Nabû-zēr-iddina sig', 'Nebuzaradán: capitán de la guardia babilónico que supervisó la destrucción de Jerusalén y la deportación de Judá. El nombre acadio Nabû-zēr-iddina significa ''Nebo ha dado descendencia.'' Nebuzaradán sirvió como rab-tabbāḥîm (''capitán de la guardia'' o ''jefe de los verdugos'') bajo Nabucodonosor II. Dirigió el incendio del templo y el palacio real (2 R 25:8-9; Jer 52:12-13), supervisó la deportación de la población de Jerusalén (2 R 25:11; Jer 39:9) e, irónicamente, se convirtió en el instrumento a través del cual Jeremías fue liberado y protegido (Jer 39:11-14; 40:1-5). Las dieciséis apariciones llevan su título oficial, subrayando su papel administrativo en la catástrofe del 586 a.C.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5019', 'spa', 'Nabucodonosor: el gran rey de Babilonia que destruyó Jerusalén y exilió a Judá. El monarca babilonio Nabucodonosor II (נְבוּכַדְרֶאצַּר / נְבוּכַדְנֶא', 'Nabucodonosor: el gran rey de Babilonia que destruyó Jerusalén y exilió a Judá. El monarca babilonio Nabucodonosor II (נְבוּכַדְרֶאצַּר / נְבוּכַדְנֶאצַּר, del acadio Nabû-kudurri-uṣur, ''Nebo, protege la frontera'') reinó del 605 al 562 a.C. y domina los libros históricos y proféticos. Sitió Jerusalén tres veces, destruyendo finalmente el templo de Salomón en el 586 a.C. y deportando a la élite de Judá (2 Re 24-25). Las dos grafías hebreas, con resh y con nun, aparecen ambas en las Escrituras; la forma con resh es históricamente más precisa. Jeremías, Ezequiel y Daniel interactúan extensamente con esta figura decisiva que se convirtió, paradójicamente, en instrumento del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5020', 'spa', 'Nabucodonosor; el poderoso rey de Babilonia que conquisto Jerusalen, destruyo el templo y exilio a Juda', 'Nabucodonosor; el poderoso rey de Babilonia que conquisto Jerusalen, destruyo el templo y exilio a Juda');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5022', 'spa', 'Nabot — el propietario jezreelita de la viña cuyo asesinato judicial por Jezabel se convirtió en paradigma de la injusticia real', 'Nabot — el propietario jezreelita de la viña cuyo asesinato judicial por Jezabel se convirtió en paradigma de la injusticia real');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5025', 'spa', 'Noba, nombre de un líder manasita y de la ciudad transjordana que conquistó y renombró en su honor', 'Este nombre designa tanto a una persona como a un lugar dentro del mismo relato. Noba fue un hombre de la tribu de Manasés que conquistó la ciudad de Kenat en Galaad y la renombró con su propio nombre (Nm 32:42). El topónimo reaparece en Jueces 8:11 como punto de referencia en la persecución de Gedeón contra los madianitas: «por el camino de los que habitan en tiendas, al oriente de Noba y Jogbeha». Este doble uso refleja la práctica antigua de que los conquistadores imprimieran su identidad personal en la geografía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5027', 'spa', 'Mirar, contemplar, observar; en Hifil: dirigir la mirada hacia algo, a menudo con atención, preocupación o intención evaluativa. En su forma Hifil, נָ', 'Mirar, contemplar, observar; en Hifil: dirigir la mirada hacia algo, a menudo con atención, preocupación o intención evaluativa. En su forma Hifil, נָבַט es el verbo principal de la Biblia hebrea para la mirada dirigida e intencionada. A diferencia de רָאָה (ver como percepción) o חָזָה (contemplación visionaria), נָבַט enfatiza el acto deliberado de volver la mirada hacia un objeto. Dios mira desde el cielo a los hijos de los hombres (Sal 33:13). Moisés tiene miedo de mirar la zarza ardiente (Éx 3:6). El salmista suplica: ''Mírame y respóndeme'' (Sal 13:3). El coreano distingue consistentemente los sentidos: 바라보다 para la mirada simple, 내려다보다 para mirar hacia abajo, 눈여겨보다 para escrutar, confirmando los contornos semánticos que la evidencia multilingüe revela a lo largo de las 70 apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5028', 'spa', 'Nebat — padre de Jeroboam I, aparece exclusivamente en la fórmula patronímica ''Jeroboam hijo de Nebat''', 'Nebat — padre de Jeroboam I, aparece exclusivamente en la fórmula patronímica ''Jeroboam hijo de Nebat''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5029', 'spa', 'Profeta: sustantivo arameo para un portavoz comisionado divinamente, cognado del hebreo נָבִיא', 'Forma aramea del conocido vocablo hebreo para profeta, que aparece exclusivamente en los libros postexílicos de Esdras. Hageo y Zacarías son identificados como los profetas que impulsaron a los exiliados retornados a reanudar la construcción del templo (Esd 5:1; 6:14). Las traducciones en todas las lenguas convergen en un único equivalente — español profeta, francés prophète, alemán Prophet — confirmando que se trata de un préstamo directo en los textos administrativos del arameo imperial, sin desplazamiento semántico alguno respecto a su contraparte hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5030', 'spa', 'Profeta: portavoz divinamente designado que proclama el mensaje de Dios al pueblo', 'Navíʾ es el término hebreo definitivo para designar al profeta — aquel que habla en nombre de Dios. Una nota editorial temprana en 1 Samuel 9:9 registra que al navíʾ antes se le llamaba roʾeh (''vidente''), reflejando un desplazamiento del énfasis visionario al proclamatorio. El vocablo abarca todo el espectro profético: patriarcas como Abraham (Gn 20:7), el incomparable Moisés (Dt 34:10), las bandas extáticas de la época de Samuel, los profetas escritores clásicos e incluso los falsos profetas condenados por Jeremías. El español ''profeta'', como el francés prophète y el alemán Prophet, deriva del griego prophetes, que a su vez traduce navíʾ en la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5031', 'spa', 'Profetisa — mujer dotada del don profético, ya sea mediante canto, oráculo o el espíritu de Dios.', 'Forma femenina de נָבִיא (''profeta''), que designa a una mujer que ejerce un papel profético. Las Escrituras nombran a cinco mujeres con este título: Miriam, quien guió a Israel en canto triunfal junto al mar Rojo (Éx 15:20); Débora, quien juzgó a Israel y acompañó a Barac a la batalla (Jue 4:4); Hulda, a quien consultaron los oficiales del rey Josías al hallarse el Libro de la Ley (2 R 22:14 = 2 Cr 34:22); la esposa innominada de Isaías (Is 8:3); y la falsa profetisa Noadías, que se opuso a Nehemías (Neh 6:14). El español ''profetisa'' preserva la marca femenina, reflejando el sufijo femenino hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5032', 'spa', 'Nebaiot, hijo primogénito de Ismael; tribu árabe asociada con Cedar', 'Nebaiot es el primogénito de Ismael y el nombre de la tribu árabe que desciende de él, estrechamente vinculada con Cedar. Las listas genealógicas de Génesis 25:13 y 1 Crónicas 1:29 lo sitúan en primer lugar entre los doce hijos de Ismael. Génesis 28:9 y 36:3 identifican a la esposa de Esaú, Majalat (Basemat), como hija de Ismael y hermana de Nebaiot. Isaías 60:7 imagina los rebaños de Nebaiot sirviendo en el altar de Dios, emparejados con Cedar, reflejando su identidad pastoril y seminómada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5034a', 'spa', 'Actuar neciamente (Qal); tratar con desprecio, deshonrar, afrentar (Piel)', 'Verbo que en Qal significa actuar necia o insensatamente, y en Piel adquiere la fuerza de tratar con desprecio y deshonra. Proverbios 30:32 emplea el Qal para advertir contra la necedad de la autoexaltación. El Piel intensifica el sentido hacia un desprecio activo: Deuteronomio 32:15 describe a Jesurún engordándose y menospreciando al Dios que lo formó. Miqueas 7:6 lamenta que un hijo deshonre a su padre. Nahúm 3:6 retrata a Dios haciendo vil a Nínive, y Jeremías 14:21 suplica que Dios no afrente su trono glorioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5034b', 'spa', 'Marchitarse, desvanecerse y caer (de la vegetación); desgastarse o agotarse; desmoronarse o desintegrarse. El verbo נָבֵל pinta la imagen de la vida q', 'Marchitarse, desvanecerse y caer (de la vegetación); desgastarse o agotarse; desmoronarse o desintegrarse. El verbo נָבֵל pinta la imagen de la vida que se escapa: hojas que caen, flores que se marchitan, fuerzas que se agotan. En su uso más frecuente, describe el marchitamiento y la caída de la vegetación: la visión de Isaías donde todas las naciones se marchitan ''como hoja de la vid'' (Is 34:4), o la promesa de que la hoja del justo ''no se marchitará'' (Sal 1:3). El consejo de Jetro a Moisés en el Sinaí revela una aplicación humana: ''ciertamente te agotarás'' (Éx 18:18) — el mismo decaimiento que alcanza a una planta alcanza a un líder sobrecargado. El cognado árabe nabala (''morir'') confirma la resonancia profunda de la palabra con la pérdida irreversible de vitalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5035a', 'spa', 'Recipiente para líquidos: odre de cuero para vino o agua, o vasija de barro; usado literal y figuradamente por su fragilidad.', 'Este sustantivo abarca dos tipos distintos de recipientes. En su primer sentido designa un odre de cuero hecho de piel de animal, usado para transportar vino o agua: Ana lleva un nevel yayin a Silo (1 Sam 1:24) y los gabaonitas presentan odres gastados a Josué. Job 38:37 extiende la imagen poéticamente: ''¿Quién puede inclinar los nivle shamayim?'' — los odres del cielo, es decir, las nubes de lluvia. En su segundo sentido se refiere a vasijas o cántaros de barro, y aquí los profetas explotan la fragilidad del recipiente: Jeremías 48:12 describe las tinajas de Moab siendo destruidas, Lamentaciones 4:2 compara a los preciados hijos de Sion con simples vasijas de barro, e Isaías 30:14 asemeja la ruina de Judá al quebrarse de un cántaro de alfarero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5035b', 'spa', 'Arpa, lira — instrumento de cuerdas usado en el culto, la celebración y la música cortesana a lo largo de la historia de Israel', 'Arpa, lira — instrumento de cuerdas usado en el culto, la celebración y la música cortesana a lo largo de la historia de Israel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5036', 'spa', 'Necio, moralmente insensato; persona ciega a las exigencias éticas y divinas, que actúa con impía desvergüenza. No describe una mera limitación intele', 'Necio, moralmente insensato; persona ciega a las exigencias éticas y divinas, que actúa con impía desvergüenza. No describe una mera limitación intelectual sino una profunda insensibilidad moral y espiritual: alguien que no percibe las demandas de Dios y actúa con presunción vergonzosa. Moisés reprende a Israel como un ''pueblo necio e insensato'' que ha olvidado a su Redentor (Dt 32:6), mientras que el salmista clama a Dios contra una nación נָבָל que blasfema su nombre (Sal 74:18). Usado como sustantivo, designa a una persona cuya necedad es voluntaria y culpable, como cuando Abigaíl reconoce que el carácter de su marido corresponde a su nombre (1 Sam 25:25). David lamenta que Abner muriera ''como muere un necio'' (2 Sam 3:33). Isaías contrasta al נָבָל con el noble (Is 32:5-6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5037', 'spa', 'Nabal -- el acaudalado pero necio carmelita cuyo nombre se volvió proverbial por su insensatez', 'Nabal -- el acaudalado pero necio carmelita cuyo nombre se volvió proverbial por su insensatez');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5038', 'spa', 'Cadáver, cuerpo muerto: un cuerpo sin vida, ya sea humano (frecuentemente en deshonra) o animal (especialmente en la ley de pureza). Derivado de una r', 'Cadáver, cuerpo muerto: un cuerpo sin vida, ya sea humano (frecuentemente en deshonra) o animal (especialmente en la ley de pureza). Derivado de una raíz que sugiere inercia o colapso, נְבֵלָה designa un cuerpo sin vida, humano o animal, con connotaciones de deshonra, impureza o abandono. Aplicado a personas, aparece frecuentemente en contextos de juicio: un cadáver insepulto expuesto a aves y bestias (Dt 28:26), el cuerpo de un profeta desobediente abandonado en el camino (1 Re 13:22-30), o los muertos de Jerusalén dados como alimento a las criaturas de la tierra (Jer 7:33). En la ley levítica, la misma palabra rige el elaborado sistema de impureza por contacto con animales muertos, donde tocar o cargar una נְבֵלָה vuelve impura a la persona hasta la tarde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5039', 'spa', 'Infamia atroz, insensatez moral; acto vergonzoso que viola las normas pactuales de Israel.', 'Mucho más que simple necedad, nevalah denota un acto de ultraje moral deliberado que escandaliza a la comunidad y transgrede las normas sagradas que rigen la vida pactual de Israel. La expresión ''cometer nevalah en Israel'' (Gn 34:7; Jue 20:6; Dt 22:21) se convirtió en fórmula fija para actos tan atroces que amenazaban el tejido de toda la comunidad, especialmente la violencia sexual y la grave inhospitalidad. En Isaías 32:6 el término se vincula con el carácter del naval, el insensato moral cuyo corazón maquina iniquidad. Los términos españoles ''infamia'' y ''vileza'' captan la dimensión social de la deshonra pública, mientras que el inglés ''folly'' minimiza la gravedad que esta palabra conllevaba.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5042', 'spa', 'Brotar, derramar palabras o alabanza (Hifil); fluir o burbujear como agua (Qal); causar fermentación o hedor.', 'Un verbo de desbordamiento incontenible, enraizado en la imagen de agua brotando de un manantial. En su única aparición en Qal, describe un ''arroyo que fluye'' como metáfora de la fuente de sabiduría (Prov 18:4). El Hifil domina el uso, transfiriendo esa energía desbordante al habla: un día ''derrama'' conocimiento al siguiente (Sal 19:2), el salmista ''profiere'' dichos oscuros (Sal 78:2) y los malvados ''vomitan'' arrogancia (Sal 59:7, 94:4). Eclesiastés 10:1 lleva el burbujeo en otra dirección: las moscas muertas hacen que el ungüento del perfumista ''fermente'' y hieda. El cognado árabe nabaʿa (''manar, brotar agua'') y el etiópico nabʿa (''llorar'') preservan el núcleo líquido que el hebreo extiende tan vívidamente al discurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5045', 'spa', 'El sur como punto cardinal; también el Néguev, la región árida al sur de Judá', 'Néguev funciona tanto como sustantivo común que significa ''sur'' como nombre geográfico propio de la estepa árida que se extiende al sur de las colinas de Judá hacia Cadés. Cuando Abraham viaja ''hacia el Néguev'' (Gn 12:9; 13:1), la palabra oscila entre dirección y destino. El lado sur del tabernáculo (Éx 26:18; 27:9) emplea néguev como punto cardinal puro, mientras que el Néguev de los ceneos o el Néguev de Caleb (1 S 27:10) designan subdistritos específicos. Las traducciones en otras lenguas suelen distinguir entre ''sur'' (dirección) y ''Néguev'' (región), confirmando los dos sentidos nucleares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5046', 'spa', 'Contar, informar, declarar; Hifil: anunciar, proclamar, revelar; Hofal: ser informado; participio: mensajero', 'Construido sobre una raíz que sugiere notoriedad o visibilidad, nagad en su predominante conjugación Hifil significa dar a conocer algo — contar, informar o declarar. Su alcance va desde el acto cotidiano de transmitir noticias (Gn 9:22, Cam contándole a sus hermanos) hasta la proclamación profética solemne (Dt 5:5, Moisés declarando la palabra de Dios). El Hofal pasivo (''le fue contado a Rebeca'', Gn 27:42) y el participio sustantivado (''vino un mensajero'', 2 S 1:5) completan un verbo cuyas formas orbitan en torno a un eje único: traer a la vista pública lo que estaba oculto o distante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5048', 'spa', 'Delante de, frente a, enfrente; en presencia de; a distancia mirando hacia; lejos de ante; contra; correspondiente a', 'Preposición y adverbio espacial construido sobre la raíz que significa ''conspicuo'' o ''lo que está al frente''. Más fuerte y preciso que el común liphnei (''delante de''), néged insiste en la orientación cara a cara: uno se sitúa directamente enfrente, a plena vista del referente. Cuando Israel acampa néged hahar (Éx 19:2), no están simplemente cerca del Sinaí, sino dispuestos de frente a la montaña. Con el prefijo direccional min marca alejamiento de la presencia de alguien (Sal 31:22). En dos ocurrencias notables en Gn 2:18, 20, describe a la ayuda hecha kenegdó — ''correspondiente a él'' — una contraparte relacional que enfrenta y complementa a Adán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5050', 'spa', 'Brillar, dar luz, iluminar — de la luz que irrumpe (Qal) o que causa resplandor disipando la oscuridad (Hifil).', 'Verbo que significa brillar o dar luz, presente tanto en Qal (intransitivo: la luz resplandece por sí misma) como en Hifil (causativo: iluminar, hacer brillar). Su uso más célebre aparece en Isaías 9:2, donde se declara que sobre los que andaban en tinieblas ''resplandeció la luz'', pasaje central en la expectativa mesiánica. La forma Hifil en Salmo 18:28 y 2 Samuel 22:29 expresa la iluminación personal de Dios: ''el SEÑOR alumbra mis tinieblas''. Job 18:5 emplea la negación — la llama del impío no brillará — como metáfora de la extinción de toda esperanza. El verbo transmite consistentemente una cualidad radiante e irruptiva de la luz divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5051', 'spa', 'Resplandor, fulgor, esplendor: brillo radiante de una fuente luminosa o divina, ocasionalmente la luz del alba. El sustantivo נֹגַהּ capta la cualidad', 'Resplandor, fulgor, esplendor: brillo radiante de una fuente luminosa o divina, ocasionalmente la luz del alba. El sustantivo נֹגַהּ capta la cualidad de un brillo deslumbrante o radiancia resplandeciente, ya sea natural o sobrenatural. Describe la luz deslumbrante que acompaña la teofanía de Dios — brasas encendidas ''por su resplandor'' (2 Sam 22:13; Sal 18:12) — y la gloria luminosa que rodea el trono-carro divino en las visiones de Ezequiel (Ez 1:4, 27-28; 10:4). Proféticamente, retrata el esplendor venidero de Sion: ''las naciones vendrán a tu luz y los reyes al resplandor de tu amanecer'' (Is 60:3). En un caso poético (Pr 4:18), evoca la radiancia creciente del alba como imagen del camino de los justos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5055', 'spa', 'Acornear, embestir con los cuernos; figuradamente arremeter o cargar en batalla.', 'Un verbo arraigado en la acción violenta de un animal que embiste con sus cuernos. En el Qal describe el cornear literal de un buey, como en las leyes casuísticas de Éxodo 21:28-32. El Piel intensifica esto en un empuje vigoroso y repetido, aplicado figuradamente a José como un toro salvaje que acornea naciones (Deut 33:17) y a los cuernos simbólicos de hierro de Sedequías (1 Re 22:11). El Hitpael en Daniel 11:40 extiende la metáfora al combate militar recíproco: dos reyes embistiéndose el uno al otro como carneros en batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5057', 'spa', 'Gobernante, lider, principe; una figura de autoridad designada, o (una vez) cosas nobles o excelentes', 'Gobernante, lider, principe; una figura de autoridad designada, o (una vez) cosas nobles o excelentes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5058', 'spa', 'Música de instrumentos de cuerda; canto o canción de burla; música como interpretación abstracta.', 'Sustantivo femenino hebreo derivado del verbo nagan (''tocar un instrumento de cuerda'') que aparece principalmente en las inscripciones de los Salmos, donde designa el acompañamiento para la adoración — binginot, ''con instrumentos de cuerda'' (Sal 4:1; 6:1; 54:1; 55:1; 67:1; 76:1). Sin embargo, la misma palabra adquiere un matiz amargo cuando denota una canción de burla: Job lamenta ''he llegado a ser su canción'' (Job 30:9), y Lamentaciones hace eco de la humillación (Lm 3:14). El ''cántico'' nocturno del salmista en el Salmo 77:6 puede expresar tanto belleza como angustia. Una aparición aislada en Lamentaciones 5:14 emplea el término para la música en sentido abstracto — ''los jóvenes dejaron su música'' — lamentando no instrumentos ni letras, sino toda la tradición viva de la interpretación musical.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5059', 'spa', 'Tocar un instrumento de cuerda; como participio, músico o tañedor que interpreta cuerdas.', 'Este verbo designa específicamente el acto de tocar un instrumento de cuerda — pulsar o rasguear las cuerdas de una lira o arpa. David fue buscado como alguien diestro en tocar (מֵיטִיב לְנַגֵּן, 1 Samuel 16:17), y su interpretación de la lira ahuyentaba el espíritu atormentador de Saúl. El participio puede funcionar como sustantivo con el significado de ''músico'' o ''tañedor'', como cuando Eliseo pide que le traigan un músico (2 Reyes 3:15) para invocar la inspiración profética, y en el Salmo 68:25 donde los instrumentistas marchan en la procesión festiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5060', 'spa', 'Tocar, alcanzar, golpear; llegar a; hacer llegar; afligir, herir; ser golpeado o derrotado', 'Un verbo cuyo campo semántico traza el arco completo del contacto, desde el toque suave hasta el golpe devastador. En su sentido más simple describe el contacto físico (Gn 3:3, ''no lo tocaréis''), pero incluso aquí una carga de tabú suele acompañar el contacto: tocar cosas santas, impuras o fronteras prohibidas. En el Hifil adquiere extensión espacial — alcanzar un destino, llegar a un punto o hacer que algo llegue. En el extremo opuesto, cuando Dios es el agente, el verbo puede significar golpear o afligir, como cuando el SEÑOR ''toca'' la casa de Faraón con plagas (Gn 12:17). El árabe separa cuidadosamente estos sentidos con raíces distintas: lamasa para tocar, balagha para alcanzar y daraba para golpear, confirmando que el hebreo reúne conceptos genuinamente distintos bajo un solo lexema.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5061', 'spa', 'Golpe, plaga, afección cutánea; un golpe o marca que abarca desde una herida física hasta una plaga divina y la ''mancha de plaga'' levítica en piel, te', 'Golpe, plaga, afección cutánea; un golpe o marca que abarca desde una herida física hasta una plaga divina y la ''mancha de plaga'' levítica en piel, tela o paredes. Derivado del verbo נָגַע (''tocar, golpear''), este sustantivo cubre todo el espectro: desde un golpe asestado entre personas hasta una plaga devastadora enviada por Dios. Su uso más frecuente es altamente técnico: la ''mancha de plaga'' examinada por el sacerdote en los elaborados procedimientos diagnósticos de Levítico 13-14. Más allá del ámbito sacerdotal, denota calamidades divinas como las plagas sobre la casa de Faraón (Gn 12:17) y la gran plaga final del Éxodo (Éx 11:1). En su sentido más íntimo, describe la ''plaga del corazón'' que solo el que la sufre conoce (1 Re 8:38).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5062', 'spa', 'Golpear, herir (activo); ser derrotado, puesto en fuga (pasivo); tropezar o chocar contra un obstáculo. נָגַף abarca todo el espectro del contacto vio', 'Golpear, herir (activo); ser derrotado, puesto en fuga (pasivo); tropezar o chocar contra un obstáculo. נָגַף abarca todo el espectro del contacto violento, desde la plaga divina hasta la derrota en batalla y el tropiezo con una piedra. En el Qal, Dios mismo es el sujeto que golpea: hiere a los primogénitos de Egipto (Éx 12:23, 27) y asesta golpes fatales a individuos (1 Sam 25:38; 2 Sam 12:15). El Nifal pasivo invierte la perspectiva: ejércitos son ''golpeados'', es decir, derrotados y puestos en fuga (Dt 28:7, 25). Un tercer sentido, pequeño pero evocador, es tropezar o dar con el pie contra una piedra (Sal 91:12; Pr 3:23), la imagen que Satanás cita a Jesús en la tentación del desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5063', 'spa', 'Golpe o plaga enviada como juicio divino; también piedra de tropiezo contra la cual se tropieza', 'Sustantivo derivado de la raíz נגף (''golpear, herir'') que designa un golpe o plaga infligida divinamente. Aparece de forma prominente en la narrativa del Éxodo, donde Dios promete que ''ninguna plaga caerá sobre vosotros'' durante la muerte de los primogénitos (Éx 12:13), y en los relatos del desierto donde la plaga amenaza a Israel por su rebeldía (Nm 16:46-47; 8:19). En un uso distintivo, Isaías 8:14 habla de un אֶבֶן נֶגֶף, una piedra de tropiezo que hace caer, metáfora de cómo Dios se convierte en obstáculo para quienes lo rechazan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5064', 'spa', 'Derramar, fluir, ser vertido; del agua vertida en tierra, lágrimas que corren o personas entregadas a la destrucción.', 'Un verbo de movimiento líquido que transita de lo literal a lo figurado con notable soltura. En su forma Nifal pasiva describe agua derramada irrecuperablemente en el suelo (2 Sam 14:14) y lágrimas que fluyen sin cesar (Lam 3:49). El Hifil causativo pone un agente detrás del derramamiento: Dios vierte su copa de ira (Sal 75:8), Jeremías suplica que sus enemigos sean ''derramados'' a espada (Jer 18:21) y Miqueas prevé las piedras de Samaria precipitándose al valle (Miq 1:6). En dos pasajes el Hifil se extiende aún más — a entregar personas a la destrucción (Ez 35:5; Sal 63:10) — como si derribar enemigos fuera una forma de verterlos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5065', 'spa', 'Presionar, impulsar, oprimir o exigir; como participio, capataz u opresor; en Nifal, ser oprimido', 'Presionar, impulsar, oprimir o exigir; como participio, capataz u opresor; en Nifal, ser oprimido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5066', 'spa', 'Acercarse, aproximarse, hacer acercar; (Qal) acercarse; (Nifal) presentarse; (Hifil) hacer acercar, presentar; (Hofal) ser acercado', 'El hebreo נָגַשׁ es un verbo de acercamiento espacial y relacional, frecuentemente sinónimo de קָרַב aunque menos frecuente. En Qal significa acercarse o aproximarse a alguien o algo. El Nifal añade un sentido reflexivo o medio: presentarse por propia iniciativa, a menudo en contextos formales o cúlticos. El Hifil es causativo: acercar a alguien o algo y, en el ámbito ritual, presentar u ofrecer sacrificios. El Hofal proporciona la pasiva: ser acercado u ofrecido. El verbo abarca la proximidad física, el acceso relacional (acercarse a un gobernante o a Dios) y la presentación ritual (traer ofrendas).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5067', 'spa', 'Montón, cúmulo — especialmente de aguas amontonadas por poder divino en el Mar Rojo o en el cruce del Jordán.', 'Sustantivo masculino que significa ''montón'' o ''cúmulo'', usado casi exclusivamente para describir el amontonamiento milagroso de las aguas. Sus apariciones más dramáticas describen la separación del Mar Rojo por parte de Dios, donde las aguas se detuvieron como un montón (Éx 15:8), y el cruce del Jordán, donde las aguas se levantaron formando un solo montón (Jos 3:13, 16). Los Salmos 78:13 y 33:7 rememoran estos eventos en contexto de adoración, usando el mismo sustantivo para evocar el poder soberano de Dios sobre la creación. El único uso posiblemente no acuático en Isaías 17:11 es textualmente incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5068', 'spa', 'Ofrecerse voluntariamente (Hitpael); mover, impulsar o incitar el corazón a actuar (Qal). Verbo de motivación interior e iniciativa generosa. En el Hi', 'Ofrecerse voluntariamente (Hitpael); mover, impulsar o incitar el corazón a actuar (Qal). Verbo de motivación interior e iniciativa generosa. En el Hitpael, describe el notable fenómeno de personas que se ofrecen voluntariamente — entregando su persona o sus recursos sin coacción. El cántico de Débora celebra a quienes ''se ofrecieron voluntariamente'' para la batalla (Jue 5:2, 9), y la campaña de David para el templo rebosa de líderes que ''ofrecieron voluntariamente'' su oro y plata (1 Cr 29:5-9). En el Qal, el enfoque se desplaza al impulso interior inicial: el espíritu de Dios o el propio corazón ''mueve'' a una persona a dar (Éx 25:2, 35:21, 29). El cognado árabe naduba (''ser noble, generoso'') ilumina la conexión de la raíz entre voluntad y nobleza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5069', 'spa', 'נְדַב (arameo) — ofrecerse voluntariamente, dar de buena gana, hacer ofrendas voluntarias', 'Este verbo arameo significa ofrecerse voluntariamente o dar de buena gana, especialmente en contextos religiosos o de beneficencia. Aparece exclusivamente en Esdras 7, donde describe las ofrendas voluntarias entregadas para la restauración del templo. El término abarca tanto el acto de ofrecerse como voluntario para el servicio como la entrega de donativos económicos con fines sagrados. Refleja el patrón de generosidad no obligatoria de la comunidad postexílica para restaurar el culto en Jerusalén. Su cognado hebreo (נָדַב) porta el mismo significado, subrayando que las verdaderas ofrendas a Dios nacen de corazones dispuestos y no de compulsión externa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5070', 'spa', 'Nadab, nombre propio que significa ''generoso'' o ''noble,'' llevado por cuatro individuos en la Biblia hebrea. Su portador más prominente es el hijo mayo', 'Nadab, nombre propio que significa ''generoso'' o ''noble,'' llevado por cuatro individuos en la Biblia hebrea. Su portador más prominente es el hijo mayor de Aarón, consagrado como sacerdote pero muerto junto a su hermano Abihú por ofrecer fuego no autorizado ante el SEÑOR (Éx 6:23; Lv 10:1; Nm 3:2-4). Un segundo portador notable es Nadab hijo de Jeroboam I, quien reinó brevemente sobre Israel antes de ser asesinado por Baasa (1 R 14:20; 15:25-31). El nombre pertenece también a un jeramelita (1 Cr 2:28, 30) y a un gabaonita (1 Cr 8:30; 9:36). Todas las traducciones lo rinden uniformemente como Nadab o Nadav.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5071', 'spa', 'Ofrenda voluntaria; don espontáneo; disposición generosa, generosidad', 'Ofrenda voluntaria; don espontáneo; disposición generosa, generosidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5074', 'spa', 'Huir, vagar, extraviarse, ser expulsado; del aleteo de aves; causativamente, ahuyentar; reflexivamente, menear la cabeza', 'Huir, vagar, extraviarse, ser expulsado; del aleteo de aves; causativamente, ahuyentar; reflexivamente, menear la cabeza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5079', 'spa', 'Impureza, inmundicia; especialmente impureza menstrual, pero extendiéndose a contaminación ritual más amplia y polución moral metafórica', 'Impureza, inmundicia; especialmente impureza menstrual, pero extendiéndose a contaminación ritual más amplia y polución moral metafórica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5080', 'spa', 'Impulsar, empujar, desterrar; en Nifal, ser desterrado; en Hifil, expulsar, seducir, desviar. Un verbo hebreo de desplazamiento forzoso que abarca la ', 'Impulsar, empujar, desterrar; en Nifal, ser desterrado; en Hifil, expulsar, seducir, desviar. Un verbo hebreo de desplazamiento forzoso que abarca la expulsión física, la seducción espiritual y el doloroso estado del exilio. En el Hifil describe a Dios expulsando naciones al destierro (Jer 16:15) o a falsos profetas desviando a Israel (Dt 13:5). El Nifal pasivo produce el conmovedor sustantivo ''el desterrado'': aquellos expulsados y dispersos a quienes Dios promete reunir (Miq 4:6; Is 56:8). Los cognados árabes طَرَدَ (expulsar) y أَضَلَّ (extraviar) reflejan tanto la dimensión física como la moral de esta raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5081', 'spa', 'Noble, príncipe; dispuesto, generoso — persona de alto rango, espíritu generoso o cualidades nobles', 'Noble, príncipe; dispuesto, generoso — persona de alto rango, espíritu generoso o cualidades nobles');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5086', 'spa', 'Aventar, dispersar; esparcir o ser esparcido como tamo ante el viento, representando el juicio divino o la dispersión irremediable.', 'Evoca la imagen vívida del viento aventando el tamo, las hojas o el rastrojo — metáfora por excelencia del juicio divino y del destino de los impíos. El Salmo 1:4 establece la escena clásica: los malvados son «como el tamo que arrebata el viento». El verbo funciona en dos voces: el Qal activo presenta a Dios o al viento como agente que dispersa a los enemigos con fuerza, mientras que el Nifal pasivo retrata a los indefensos arrastrados sin remedio. En español ambos polos se captan con ''aventar'' (esparcir al viento) y ''ser aventado'' (ser esparcido).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5087', 'spa', 'Hacer voto, hacer una promesa solemne a Dios; comprometerse con una ofrenda, servicio o acto de devocion, a menudo condicionalmente', 'Hacer voto, hacer una promesa solemne a Dios; comprometerse con una ofrenda, servicio o acto de devocion, a menudo condicionalmente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5088', 'spa', 'Un voto — una promesa solemne hecha a Dios, comprometiendo sacrificio, servicio o devoción a cambio del favor divino.', 'Un voto — una promesa solemne hecha a Dios, comprometiendo sacrificio, servicio o devoción a cambio del favor divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5090a', 'spa', 'Conducir o arrear ganado; guiar o dirigir personas; guiar con cuidado (Piel); llevar o arrebatar por la fuerza', 'Conducir o arrear ganado; guiar o dirigir personas; guiar con cuidado (Piel); llevar o arrebatar por la fuerza');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5091', 'spa', 'Lamentarse, gemir o llorar con duelo audible', 'Este verbo describe el acto de expresar dolor mediante gemidos y lamentos audibles. En 1 Samuel 7:2, marca un momento decisivo: «toda la casa de Israel se lamentaba en pos del SEÑOR», expresando su anhelo durante la ausencia del arca. Ezequiel 32:18 ordena al profeta: «lamenta por la multitud de Egipto y hazla descender», convirtiendo el duelo profético en juicio proclamado. Miqueas 2:4 anticipa: «En aquel día se entonará contra vosotros un canto de burla y se lamentará con amargo lamento». El término abarca desde el clamor espontáneo hasta el lamento ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5092', 'spa', 'Lamento, endecha: canto fúnebre o clamor de duelo, especialmente en contextos proféticos de juicio divino', 'Sustantivo que designa un clamor fuerte y doliente o canto de duelo, estrechamente asociado a anuncios proféticos de juicio divino. En Jeremías 9:10-20, aparece junto a las lágrimas (דִּמְעָה) y la elegía fúnebre (קִינָה), pintando un vívido cuadro de dolor comunitario. Amós 5:16 habla de plañideros profesionales ''diestros en el lamento'' (יֹדְעֵי נֶהִי), revelando una institución del antiguo Cercano Oriente de plañideros entrenados. El término español ''endecha'' captura la cualidad formalizada y ritual de este duelo, distinguiéndolo del llanto espontáneo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5095', 'spa', 'Guiar o conducir, especialmente a un abrevadero o lugar de descanso; llevar suavemente a paso mesurado.', 'Un verbo cuyo Piel significa guiar o conducir a alguien a lo largo de un camino, frecuentemente con la connotación de llevarle hacia agua o reposo. La instancia más entrañable es Salmo 23:2: ''Me conduce junto a aguas de reposo'', donde la imagen pastoril captura el sentido esencial de guiar hacia el refrigerio. Dios guía a su pueblo redimido (Éx 15:13) y los líderes conducen a los cautivos a lugar seguro (2 Cr 28:15). La única aparición en Hitpael (Gn 33:14) añade un matiz de delicadeza: Jacob ''conducirá lentamente'' para acomodarse al paso de los niños y los rebaños lactantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5096', 'spa', 'Nahalal o Nahalol, ciudad levítica en el territorio de Zabulón', 'Este topónimo aparece con ligeras variantes ortográficas (Nahalal en Josué, Nahalol en Jueces) para designar la misma ciudad zabulonita asignada a los levitas. Josué 19:15 la incluye entre las ciudades de la herencia de Zabulón, y 21:35 la designa como ciudad levítica. Jueces 1:30 señala que Zabulón «no expulsó a los habitantes de Nahalol», quienes quedaron como tributarios. Su ubicación exacta se desconoce, aunque se situaba en algún punto del territorio de Zabulón en la Baja Galilea. La Septuaginta presenta variaciones significativas al transliterar el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5098', 'spa', 'Gruñir (como león devorando presa) o gemir (de sufrimiento o angustia)', 'Una vívida palabra sonora que abarca dos registros de vocalización gutural profunda. En contextos de depredadores, designa el gruñido bajo y sostenido del león sobre su presa, distinto del rugido inicial del ataque. Isaías la emplea dos veces para retratar el aterrador avance de Asiria (Is 5:29-30). En contextos humanos, pasa al gemido de quien padece sufrimiento físico o emocional, como el arrepentido que sufre en Proverbios 5:11 y los que lloran en silencio de Ezequiel 24:23.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5102a', 'spa', 'נָהַר — fluir, afluir hacia algo; moverse en abundancia como una corriente', 'Este verbo significa fluir o afluir, y en la Biblia hebrea se usa siempre en sentido figurado para describir a personas que confluyen como agua hacia un destino. La imagen evoca ríos que desembocan en el mar o afluentes que convergen en un punto central. Los textos proféticos lo emplean para representar a las naciones afluyendo hacia Jerusalén para adorar, o a Israel confluyendo hacia las bendiciones de Dios. El término captura un movimiento que es a la vez abundante, como el agua que fluye, y direccional, orientado hacia una meta específica. Transmite la imagen de una convergencia entusiasta e irresistible hacia un centro de bendición o culto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5103', 'spa', 'Río (arameo) — el Éufrates o un río en general; usado en Esdras para la región del Trans-Éufrates y en Daniel para un río de fuego.', 'Este sustantivo arameo (נְהַר) aparece casi exclusivamente en la frase formularia ''al otro lado del Río'' (עֲבַר נַהֲרָה) en Esdras, designando la satrapía persa al oeste del Éufrates — la región administrativa que incluía a Judá. El término funciona como abreviatura político-geográfica: la correspondencia imperial persa hace referencia reiterada a gobernadores y pueblos ''al otro lado del Río'' (Esd 4:10–20; 5:3, 6; 6:6, 13; 7:21, 25). Su única aparición fuera del contexto del Éufrates es Daniel 7:10, donde un ''río de fuego'' (נְהַר דִּי נוּר) fluye desde la presencia del Anciano de Días — una imagen apocalíptica sobrecogedora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5104', 'spa', 'Río, corriente: curso de agua perenne; con frecuencia ''el Río'' (el Éufrates) o torrentes cósmicos poéticos', 'Nahar designa un curso de agua considerable y de flujo continuo, distinguido del nachal (wadi estacional) por su permanencia. Cuando se emplea con artículo (''el Río''), típicamente se refiere al Éufrates, el gran río que definía el límite nororiental de la tierra prometida (Gn 15:18; Dt 1:7; Jos 24:2). El compuesto Aram Naharáyim (''Aram de los dos ríos'', Gn 24:10) nos da Mesopotamia. En la poesía, nahar adquiere resonancias cósmicas: ríos que baten palmas (Sal 98:8), corrientes primordiales que alzan su voz contra Dios (Sal 93:3) y arroyos escatológicos que fluyen desde el templo (Ez 47:1-12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5106', 'spa', 'Impedir, prohibir, desalentar; restringir a alguien de cumplir un voto, frustrar un plan o desanimar a una comunidad para que no actúe.', 'Abarca dos tipos de obstrucción relacionados pero distintos: la restricción legal y el desaliento psicológico. En la legislación sobre votos de Números 30, un padre o esposo puede ''prohibir'' el juramento de una mujer, anulándolo efectivamente al negar su consentimiento el mismo día que lo escucha. Pero en Números 32:7-9 la misma raíz describe el devastador efecto psicológico del informe maligno de los espías: ''desalentaron el corazón'' de Israel para que no entrara en la Tierra Prometida. El Salmo 33:10 amplía el vocablo a escala cósmica: el SEÑOR ''frustra'' los designios de las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5107', 'spa', 'נוּב — dar fruto, producir, florecer; generar resultados', 'Este verbo poético significa dar fruto, producir o florecer, y aparece exclusivamente en la literatura sapiencial y litúrgica. La imagen proviene de árboles frutales que dan su cosecha, aplicada figuradamente a personas justas que producen sabiduría, a los impíos cuya riqueza aumenta, o a Dios que hace florecer a los jóvenes. El término enfatiza la fecundidad y la productividad como resultados visibles de una condición subyacente: la rectitud produce sabiduría tan naturalmente como un árbol sano produce fruto. La forma Polel intensifica la idea hacia «hacer florecer» o «hacer fructificar abundantemente».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5110', 'spa', 'Moverse de un lado a otro, vagar; mostrar duelo o compasión agitándose, asintiendo o gimiendo; causativamente, ahuyentar', 'Moverse de un lado a otro, vagar; mostrar duelo o compasión agitándose, asintiendo o gimiendo; causativamente, ahuyentar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5116a', 'spa', 'Morada, habitacion; pastizal o pradera para rebanos; redil o lugar de descanso donde los animales reposan seguros', 'Morada, habitacion; pastizal o pradera para rebanos; redil o lugar de descanso donde los animales reposan seguros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5117', 'spa', 'Descansar, reposar, asentarse (Qal); dar descanso o depositar (Hifil); del reposo de personas tras el trabajo, del Espíritu que se posa, o de Dios con', 'Descansar, reposar, asentarse (Qal); dar descanso o depositar (Hifil); del reposo de personas tras el trabajo, del Espíritu que se posa, o de Dios concediendo alivio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5121', 'spa', 'Naioth — lugar en o cerca de Ramá asociado con la comunidad profética de Samuel y la profecía extática', 'Naioth (נָיוֹת) designa un lugar en o cerca de Ramá, vinculado con Samuel y una comunidad de profetas. Cuando David huyó de Saúl, acudió a Samuel «en Naioth en Ramá» (1 Sam 19:18). Saúl envió tres grupos de mensajeros para apresarlo, pero cada vez el Espíritu cayó sobre ellos y profetizaron (1 Sam 19:19-21). Saúl mismo fue y también profetizó todo el día y la noche (1 Sam 19:22-24). David huyó entonces de Naioth hacia Jonatán (1 Sam 20:1). El nombre probablemente deriva de naveh (''morada''), lo que sugiere una residencia comunitaria profética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5122', 'spa', 'Muladar, estercolero o montón de ruinas y escombros', 'Este préstamo arameo aparece en Esdras y Daniel para referirse a un estercolero o montón de escombros. El rey Darío decreta que quien altere su edicto será empalado en una viga de su propia casa, y «su casa será convertida en muladar» (Esd 6:11). Daniel lo emplea dos veces en amenazas reales: las casas serán reducidas a muladares como castigo por no interpretar sueños o por blasfemar contra Dios. El término evoca una degradación total: la morada convertida en basural, imagen de ruina absoluta y humillación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5123', 'spa', 'Dormitar, cabecear, adormecerse — sueño ligero o somnolencia negligente, distinto del sueño profundo (yashen).', 'Verbo que significa dormitar, cabecear o adormecerse, representando una etapa de sueño más ligera que yashen (''dormir profundamente''). Su aparición más célebre es la enfática doble negación del Salmo 121:3-4: el guardián de Israel ''no se dormitará ni dormirá'', emparejando num y yashen como un merismo de vigilia total. En sentido negativo, describe negligencia culpable: los pastores de Asiria dormitan mientras su rebaño se dispersa (Nah 3:18) y los centinelas de Israel aman la somnolencia (Isa 56:10). Isaías 5:27 alaba al incansable ejército asirio: ''ninguno entre ellos dormita ni duerme''. El español preserva bien el matiz con ''dormitar'' frente a ''dormir''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5126', 'spa', 'Nun — nombre propio, padre de Josué, identificado consistentemente en el patronímico ''Josué hijo de Nun''', 'Nun — nombre propio, padre de Josué, identificado consistentemente en el patronímico ''Josué hijo de Nun''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5127', 'spa', 'Huir, escapar, correr del peligro; como participio: fugitivo; Hifil: poner en fuga, ahuyentar', 'El verbo hebreo principal para la huida ante el peligro, la batalla o la amenaza. Su imagen nuclear es un movimiento rápido impulsado por el miedo — ya sea Israel huyendo ante sus enemigos (Lv 26:17), Jonás huyendo del SEÑOR, o el mar mismo ''huyendo'' ante la reprensión de Dios (Sal 114:3). El cognado árabe nasa (''agitarse, moverse de un lado a otro'') conserva el sentido subyacente de movimiento agitado. El Hifil causativo añade la dimensión de provocar la huida, mientras que el participio se cristaliza en un sustantivo que significa ''fugitivo'' o ''refugiado''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5128', 'spa', 'Temblar, oscilar, tambalear, vagar o sacudir; de movimiento inestable, deambular fugitivo, temblor por miedo y sacudimiento deliberado', 'Temblar, oscilar, tambalear, vagar o sacudir; de movimiento inestable, deambular fugitivo, temblor por miedo y sacudimiento deliberado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5130b', 'spa', 'Mecer, blandir o agitar de un lado a otro; usado para ofrendas rituales mecidas, empunar herramientas, gestos amenazantes y cribado', 'Mecer, blandir o agitar de un lado a otro; usado para ofrendas rituales mecidas, empunar herramientas, gestos amenazantes y cribado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5133', 'spa', 'נוֹצָה — plumaje, plumas; la cobertura completa de las alas de un ave', 'Este sustantivo femenino designa el plumaje o las plumas, es decir, la cobertura colectiva de las alas y el cuerpo de un ave. Aparece en contextos que describen aves majestuosas de presa como el águila y también el avestruz, enfatizando el despliegue visual impresionante de un plumaje completo. Metafóricamente, el abundante plumaje del águila simboliza poder real y esplendor, aplicado a Nabucodonosor y al faraón de Egipto en Ezequiel. En Levítico hay un uso singular relacionado con el sacrificio de aves, donde el término puede referirse a las plumas que deben retirarse, aunque algunos lo interpretan como la «suciedad» del buche.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5135', 'spa', 'fuego — el elemento del fuego, especialmente en visiones del juicio divino y del horno ardiente (arameo)', 'fuego — el elemento del fuego, especialmente en visiones del juicio divino y del horno ardiente (arameo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5137a', 'spa', 'Rociar ritualmente (Hifil); salpicar o chorrear como sangre que salta (Qal)', 'Rociar ritualmente (Hifil); salpicar o chorrear como sangre que salta (Qal)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5138', 'spa', 'Guiso o potaje; un plato hervido de legumbres o verduras, la comida cocida cotidiana del antiguo Israel.', 'Un plato hervido preparado con lentejas u otras legumbres, típicamente cocido en una olla sobre el fuego. El ejemplo más famoso es el guiso de lentejas por el cual Esaú vendió su primogenitura a Jacob (Gn 25:29-34), donde el texto lo especifica como ''guiso de lentejas'' (nezid adashim). Reaparece en la narrativa de Eliseo cuando una calabaza silvestre se añade accidentalmente a la olla de guiso de la comunidad profética (2 R 4:38-40). En Hageo 2:12, se menciona como alimento doméstico ordinario en una consulta sobre pureza sacerdotal. La palabra evoca un plato espeso y cocido a fuego lento, sencillo pero de gran peso narrativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5139', 'spa', 'Nazareo (consagrado por voto); persona consagrada, príncipe distinguido; vid sin podar dejada sin cultivar', 'Nazareo (consagrado por voto); persona consagrada, príncipe distinguido; vid sin podar dejada sin cultivar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5140', 'spa', 'Fluir, correr, gotear o destilar; usado para agua que corre por los wadis, lluvia que cae de las nubes y palabras que destilan suavemente como el rocí', 'Fluir, correr, gotear o destilar; usado para agua que corre por los wadis, lluvia que cae de las nubes y palabras que destilan suavemente como el rocío');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5141', 'spa', 'Anillo de oro usado como adorno personal — como pendiente, aro nasal u anillo ornamental en general', 'Anillo de oro usado como adorno personal — como pendiente, aro nasal u anillo ornamental en general');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5142', 'spa', 'נְזַק (arameo) — sufrir daño, ser perjudicado o causar perjuicio', 'Este verbo arameo significa sufrir daño o perjuicio, y aparece en el texto bíblico únicamente en Daniel y Esdras. Describe tanto el padecimiento personal de pérdida como la acción de causar daño a otros, especialmente en contextos políticos: pérdida de ingresos para el rey o daño sedicioso a los intereses reales. La raíz se encuentra en acadio (dañar) y en arameo judío posterior (astucia, daño). Aparecen tanto formas pasivas (sufrir perjuicio) como causativas activas (causar daño), lo que demuestra la versatilidad del verbo para describir el daño desde distintas perspectivas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5144a', 'spa', 'Consagrarse o dedicarse a sí mismo; apartarse con propósito sagrado o en apostasía', 'Esta forma Nifal posee la fuerza reflexiva de apartarse a uno mismo con un propósito sagrado o, trágicamente, con uno profano. En Oseas 9:10, Israel ''se consagró'' al vergonzoso Baal, mientras que en Ezequiel 14:7 el apóstata ''se aparta'' del Señor. Levítico 22:2 y 15:31 emplean la misma raíz para la separación sacerdotal de las cosas santas a fin de evitar la profanación. Zacarías 7:3 la utiliza en el contexto de la abstinencia ritual durante el ayuno. El carácter reflexivo y volitivo del acto es central en todos los usos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5144b', 'spa', 'Vivir como nazareo; hacer o cumplir un voto de abstinencia consagrada al SEÑOR', 'Exclusivo de Números 6, este denominativo Hifil derivado de nazir describe el acto formal de asumir o mantener un voto nazareo. El voto implica abstenerse de vino y productos de la vid, evitar todo contacto con cadáveres y dejar crecer el cabello sin cortarlo. Las cinco apariciones se enmarcan en la legislación sobre el nazareato, y la frase repetida «para el SEÑOR» en el hebreo ancla cada uso en el servicio devoto a Dios. El español «separarse» y «consagrarse» captan la doble dimensión del término: la renuncia y la dedicación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5145', 'spa', 'Consagración o separación nazarea; también corona o diadema que denota autoridad real o sacerdotal.', 'Consagración o separación nazarea; también corona o diadema que denota autoridad real o sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5146', 'spa', 'Noe -- el patriarca justo que construyo el arca y sobrevivio al gran diluvio, ancestro de toda la humanidad posdiluviana', 'Noe -- el patriarca justo que construyo el arca y sobrevivio al gran diluvio, ancestro de toda la humanidad posdiluviana');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5148', 'spa', 'Guiar, conducir o dirigir por un camino; de Dios guiando a su pueblo, o de asentar a alguien en un lugar', 'Guiar, conducir o dirigir por un camino; de Dios guiando a su pueblo, o de asentar a alguien en un lugar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5150', 'spa', 'Consuelo, consolación o sentimiento compasivo hacia quien sufre', 'Este sustantivo describe tanto el consuelo ofrecido a quienes están en aflicción como la conmoción interna de compasión. Isaías promete que Dios restaurará y dará «consuelo» a los enlutados. Oseas lo emplea para expresar el conflicto interior de Dios: «mi corazón se conmueve dentro de mí; se enciende toda mi compasión», la lucha divina entre el juicio y la misericordia. Zacarías registra «palabras consoladoras» pronunciadas por el ángel. El término abarca tanto el movimiento emocional hacia el que sufre como la expresión verbal o activa de la consolación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5152', 'spa', 'Nacor: nombre de dos figuras patriarcales, el abuelo y el hermano de Abraham', 'Nacor: nombre de dos figuras patriarcales, el abuelo y el hermano de Abraham');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5154', 'spa', 'Cobre o bronce; término poético para el metal usado figuradamente para expresar fuerza, dureza u obstinación inflexible', 'Sinónimo poético del más común necosheth, que designa el cobre o su aleación, el bronce. Job 28:2 describe el cobre fundido a partir del mineral, mientras que en la imaginería bélica un guerrero doblega un «arco de bronce» (2 Sam 22:35; Sal 18:35). La palabra posee una rica fuerza figurada: los huesos de behemot son como «tubos de bronce» (Job 40:18), los cascos de Sion se convierten en bronce para aplastar a los opresores (Miq 4:13) y una frente obstinada es llamada de bronce (Isa 48:4). La maldición de Levítico 26:19 amenaza con que el cielo se volverá como bronce: inflexible y sin lluvia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5157', 'spa', 'Heredar, tomar posesión, dar en herencia; abarca recibir una porción hereditaria, distribuir tierras y legar propiedades.', 'Heredar, tomar posesión, dar en herencia; abarca recibir una porción hereditaria, distribuir tierras y legar propiedades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5158a', 'spa', 'Wadi, torrente estacional, arroyo — cauce o barranco que fluye en época de lluvias y se seca en verano; a veces río perenne o torrentera.', 'Nachal designa uno de los rasgos más característicos del paisaje levantino: el cauce estacional que talla un valle entre las rocas, corre como arroyo en los meses de lluvia y queda seco en verano. La mayoría de sus 140 apariciones (~82x) se refieren a wadis con nombre propio — Cedrón, Arnón, Besor, Escol — como accidentes geográficos e hidrológicos a la vez. Pero nachal también puede subrayar el valle como terreno (Gn 26:17), describir un río o arroyo perenne en contextos de abundancia (Dt 8:7), o evocar la torrentera devastadora de las aguas de crecida repentina en la poesía (Sal 124:4). El árabe conserva una distinción similar entre wadi (estacional) y nahr (perenne).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5159', 'spa', 'Herencia, posesión; tierra asignada o patrimonio; heredad pactual donde Dios o su pueblo son la porción atesorada.', 'Nakhalah habla de posesión permanente e inalienable — ante todo, los lotes tribales de la tierra prometida (Nm 27:7; Jos 13-19), pero también la asombrosa reivindicación pactual de que Dios mismo es la herencia de uno (Sal 16:5-6) o de que Israel es la heredad propia de Dios (Dt 4:20). El español heredad y herencia, el francés héritage y el alemán Erbe reflejan todos esa conexión profunda entre identidad y tierra. El vocablo entrelaza derecho de propiedad, lealtad familiar y promesa divina en un solo concepto que atraviesa como un hilo conductor desde el Génesis hasta los Salmos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5161', 'spa', 'Nehelamita; gentilicio que identifica al profeta Semaías, opositor de Jeremías en Babilonia', 'Este adjetivo gentilicio identifica a Semaías como «el nehelamita» en la correspondencia de Jeremías con los exiliados en Babilonia. El topónimo Nehelam no está atestiguado en ningún otro pasaje bíblico, lo que sugiere un nombre familiar o una aldea desconocida. Jeremías pronuncia juicio contra Semaías el nehelamita por profetizar falsamente y aconsejar rebelión contra la palabra del SEÑOR. Su uso uniforme en las traducciones como gentilicio propio confirma que funciona como epíteto identificativo, no como sustantivo común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5162', 'spa', 'Consolar, confortar; arrepentirse o desistir; compadecerse — abarca el consuelo dado, el cambio divino de rumbo y el autoconsuelo reflexivo.', 'Una de las raíces de mayor carga emocional del Antiguo Testamento, נחם recorre todo el arco desde dar consuelo hasta recibirlo, desde el arrepentimiento divino hasta la compasión humana. En Piel es el verbo clásico para consolar a los que lloran — como José consoló a sus hermanos (Gn 50:21) o David fue consolado tras la muerte del hijo de Betsabé (2 S 12:24). En Nifal toma un giro radicalmente distinto: Dios ''se arrepiente'' o desiste del juicio previsto, como en el episodio del becerro de oro (Éx 32:14) o a través de las intercesiones de Amós (Am 7:3, 6). El árabe cognado نَحَمَ significa ''jadear'', evocando el hondo suspiro que acompaña tanto al duelo como al cambio de parecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5166', 'spa', 'Nehemías; nombre propio que significa ''Yah consuela'', llevado por el gobernador de Judá y otras dos figuras bíblicas.', 'Nombre teofórico que significa ''YHWH consuela'', célebre sobre todo por Nehemías hijo de Hacalías, copero del rey persa Artajerjes que llegó a ser gobernador de Judá y dirigió la reconstrucción de las murallas de Jerusalén (Neh 1:1; 8:9). El nombre lo llevan también un gobernante de la mitad del distrito de Bet-sur (Neh 3:16) y uno de los doce líderes que regresaron del exilio con Zorobabel (Esd 2:2). En todas las tradiciones cristiana y judía el nombre se conserva fonéticamente: Nehemías, Néhémie, Nehemia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5168', 'spa', 'Nosotros (pronombre personal de primera persona del plural, forma abreviada de אֲנַחְנוּ)', 'Forma abreviada del pronombre estándar de primera persona del plural אֲנַחְנוּ («nosotros»). Aparece con poca frecuencia en la Biblia hebrea, siempre en discurso directo cargado de emoción: los hermanos de José proclamando su inocencia (Gn 42:11), Israel quejándose contra Moisés en el desierto (Éx 16:7-8), los rubenitas comprometiéndose a cruzar el Jordán armados (Nm 32:32) y la confesión comunitaria de Lamentaciones 3:42. Formas cognadas aparecen en árabe, etiópico y arameo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5172', 'spa', 'Practicar adivinación, interpretar presagios — leer señales o portentos; prohibido en Israel, aunque usado respecto a la copa de José', 'El verbo נָחַשׁ (nachash II) significa practicar la adivinación o interpretar presagios. El Código de Santidad lo prohíbe (Lev 19:26) y Deuteronomio condena al menachesh como abominación (Deut 18:10). Ambos reinos cayeron en este pecado (2 Re 17:17; 21:6; 2 Cr 33:6). Sin embargo, el mayordomo de José afirma que la copa de plata es aquella «con la que mi señor adivina» (Gn 44:5, 15), aunque se debate si se trata de lecanomancia genuina o de una estratagema. Labán «adivinó» que el Señor lo bendijo por medio de Jacob (Gn 30:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5174', 'spa', 'Bronce o cobre (arameo), usado en Daniel para la imaginería metálica de la estatua de Nabucodonosor y visiones afines.', 'Sustantivo arameo para bronce o cobre, cognado del hebreo más común נְחֹשֶׁת. Las nueve apariciones se encuentran en el libro de Daniel, donde el bronce tiene un peso simbólico importante. En la estatua del sueño de Nabucodonosor, el vientre y los muslos son de bronce (Dan 2:32), representando el tercer reino. El metal reaparece al ser destruida la estatua (2:35, 45) y en la descripción de las garras de la cuarta bestia (7:19). Las bandas de bronce y hierro sobre el tronco cortado (Dan 4:15, 23) extienden la imagen de la alegoría política al juicio personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5175', 'spa', 'Serpiente, culebra; la criatura arquetípica del Edén y símbolo de peligro, astucia y juicio divino', 'Serpiente, culebra; la criatura arquetípica del Edén y símbolo de peligro, astucia y juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5176', 'spa', 'Najás, nombre propio masculino de un rey amonita en tiempos de Saúl y David, y posiblemente de otros individuos.', 'Najás es principalmente el nombre del rey amonita que sitió Jabes de Galaad, provocando la primera acción militar de Saúl (1 Sam 11:1-2). Su muerte dio ocasión al gesto diplomático de condolencia de David hacia su hijo Hanún, que desembocó en guerra (2 Sam 10:2; 1 Cr 19:1-2). Un Najás distinto se menciona como padre de Abigail y Sarvia (2 Sam 17:25), aunque algunos eruditos identifican a este personaje con Isaí. El nombre mismo significa ''serpiente'' en hebreo, pero las traducciones multilingües lo tratan exclusivamente como nombre propio transliterado. La Septuaginta lo traduce consistentemente como Naas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5177', 'spa', 'Naasón, hijo de Aminadab; príncipe de la tribu de Judá durante el período del desierto y antepasado en la línea davídica', 'Nombre personal del jefe de la tribu de Judá durante el Éxodo y las peregrinaciones por el desierto. Naasón, hijo de Aminadab, fue el príncipe tribal que presentó la primera ofrenda de dedicación del tabernáculo (Nm 7:12-17) y dirigió el campamento de Judá en la marcha (Nm 2:3; 10:14). También era cuñado de Aarón a través de su hermana Elisabet (Éx 6:23). Las genealogías de Rut 4:20-22 y 1 Crónicas 2:10-11 lo sitúan en la línea ancestral directa de Judá a David, convirtiéndolo en un eslabón clave del linaje mesiánico. La Septuaginta translitere su nombre como Naassōn.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5178a', 'spa', 'Cobre o bronce como metal bruto y material labrado; en forma dual, grillos de bronce para atar prisioneros.', 'Uno de los metales mencionados con mayor frecuencia en la Biblia hebrea, נְחֹשֶׁת abarca toda la gama desde el mineral de cobre en bruto (Dt 8:9) hasta el bronce refinado empleado en la construcción del tabernáculo y del templo. A Tubal-caín se le atribuye haber sido el primero en forjarlo (Gn 4:22), y el templo de Salomón requirió cantidades enormes (1 R 7:14-47). La forma dual נְחֻשְׁתַּיִם aparece exclusivamente para designar grillos — los grilletes pareados que se colocaban a prisioneros como Sansón (Jue 16:21) y el rey Sedequías (2 R 25:7). El español y el francés traducen uniformemente bronce, mientras que el alemán distingue Kupfer (en bruto) de Bronze (trabajado).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5181', 'spa', 'Descender, bajar; presionar o doblar; hundirse; hacer descender; ser quebrantado — verbo poético de movimiento descendente y fuerza', 'Verbo poético con fuertes raíces arameas, usado casi exclusivamente en pasajes literarios elevados. Describe el movimiento descendente en términos físicos y metafóricos vívidos: flechas que se clavan en la carne (Sal 38:2), la mano de Dios que desciende en castigo, una reprensión que penetra el corazón (Prov 17:10) y los impíos que bajan al Seol en un instante (Job 21:13). El Piel intensifica el sentido hacia presionar o doblar hacia abajo, como cuando Dios adiestra las manos del guerrero para que un arco de bronce sea doblegado (2 Sam 22:35; Sal 18:34). Las traducciones al español como «se clavaron» para el Nifal muestran la dificultad de encontrar equivalentes precisos en otras lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5182', 'spa', 'Verbo arameo: descender, bajar (Peal); depositar, colocar, almacenar (Hafel); ser depuesto (Hofal).', 'Verbo arameo que aparece en Daniel y Esdras, cognado del árabe ''nazala'' (descender). En el tronco Peal, un vigía celestial ''desciende del cielo'' en el sueño de Nabucodonosor (Dn 4:13, 23). El causativo Hafel cambia al registro administrativo: documentos reales son ''depositados'' en los archivos babilónicos (Esd 6:1) y se ordena que los utensilios del templo sean colocados de vuelta en Jerusalén (Esd 5:15; 6:5). El pasivo Hofal ofrece el uso más dramático: Nabucodonosor ''fue depuesto'' de su trono real cuando su corazón se enalteció en orgullo (Dn 5:20). Así, el verbo transita del descenso físico al derrocamiento político.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5183a', 'spa', 'Quietud, reposo, tranquilidad; estado de calma apacible o descanso satisfactorio, opuesto al afán y la agitación.', 'Sustantivo femenino que transmite un profundo sentido de quietud, reposo o tranquilidad asentada. Isaías 30:15 lo empareja con הַשְׁקֵט (''sosiego''), declarando que en la quietud y la confianza está la fortaleza de Israel, afirmación teológica poderosa sobre la dependencia reposada en Dios. Eclesiastés lo emplea como antítesis del afán incesante: ''un puñado de quietud'' vale más que ''dos puñados de trabajo'' (4:6). En Proverbios 29:9 contrasta con la furia y la burla, sugiriendo compostura ante la necedad. El término evoca una calma contemplativa y profunda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5184', 'spa', 'Najat — nombre de un jefe de clan edomita, un levita y un supervisor del templo bajo Ezequías', 'Nombre propio que llevan tres individuos distintos en el Antiguo Testamento. El primero es un nieto de Esaú por línea de Reuel, incluido entre los jefes de clan edomitas (Gn 36:13, 17; 1 Cr 1:37). Un segundo Najat aparece en la genealogía levítica como descendiente de Elcana (1 Cr 6:26), probablemente variante de Tohu/Tóaj. El tercero sirvió como supervisor del templo administrando contribuciones y diezmos durante las reformas de Ezequías (2 Cr 31:13). La Septuaginta transcribe el nombre de diversas formas: Nachoth, Nacheth y Naath.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5185', 'spa', 'que desciende, que baja — que se mueve hacia abajo, especialmente hacia un lugar específico', 'Este adjetivo participial aparece en 2 Reyes durante la advertencia de Eliseo al rey de Israel sobre los movimientos de tropas arameas. El profeta revela dónde el enemigo está ''descendiendo'' o ''bajando'', quizá hacia un valle o una posición más baja para una emboscada. El texto presenta dificultades textuales, y las versiones griegas antiguas sugieren leer ''escondidos'' o ''al acecho'' en su lugar. En cualquier caso, el conocimiento sobrenatural de Eliseo otorga a Israel una ventaja táctica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5186', 'spa', 'Extender, inclinar, desviar, desplegar — verbo de extensión direccional: literal (mano, brazo, tienda) o figurado (corazón, oído, justicia).', 'Este verbo (216x) cubre tanto el estiramiento físico — mano, brazo, cortinas de tienda — como la inclinación o desviación metafórica. En Qal significa ''extender'' (Éx 7:5), ''apartarse'' (Gn 38:16) o ''armar una tienda'' (Gn 12:8). Las formas causativas Hifil significan ''inclinar'' (el corazón o el oído hacia la instrucción) o ''desviar'' (a alguien de su camino). Los participios describen a Dios como quien ''extiende los cielos'' (Is 40:22; Job 9:8). El árabe نطو y مَدَّ (extender), مَالَ (inclinar), el español extender/inclinar y el suajili kunyoosha/kuelekeza convergen todos en ese doble sentido de extensión y desviación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5187', 'spa', 'cargado de, que lleva — que soporta o está cargado con algo pesado', 'Este adjetivo aparece en el oráculo de juicio de Sofonías contra el barrio mercantil de Jerusalén. El profeta anuncia la perdición de ''los cargados de plata'', los comerciantes adinerados cuyas riquezas no podrán salvarlos. Es un juicio económico: quienes acumularon riqueza lo perderán todo. La palabra sugiere estar agobiado o sobrecargado con algo, aquí aplicada a mercaderes que llevan plata. La imagen anticipa la catástrofe venidera cuando la riqueza material resulte inútil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5189', 'spa', 'Sarmientos, pámpanos o ramas extendidas de una vid', 'Este término describe los brotes o sarmientos que se extienden de la vid, las partes que se propagan y trepan. Isaías lo emplea en imágenes de juicio: Dios «cortará los sarmientos» de la viña que representa a una nación. Jeremías retoma esta imagen al ordenar a los destructores que «arranquen sus sarmientos», despojando la vid de su crecimiento. Jeremías 48 lo usa metafóricamente para la antigua prosperidad de Moab: «tus sarmientos cruzaron el mar», evocando una influencia extensiva. El término enfatiza la cualidad expansiva de la vid: un crecimiento que extiende territorio o influencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5190', 'spa', 'נָטַל — levantar, cargar, llevar; alzar y transportar', 'Este verbo es un sinónimo poético del más común נָשָׂא, y significa levantar, cargar o llevar. Aparece con poca frecuencia en el hebreo bíblico, principalmente en textos poéticos elevados. La imagen implica alzar algo y sostener su peso, ya sea de manera literal (Dios que levanta las islas como polvo) o figurada (sostener al pueblo con compasión, imponer responsabilidad o aceptar una carga). La conjugación Piel puede intensificar el significado a «llevar consigo» o «transportar». El término sugiere no solo un levantamiento momentáneo, sino una carga sostenida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5192', 'spa', 'peso, carga — la pesadez o el peso de algo', 'Este sustantivo aparece en Proverbios en un dicho que compara el peso de la arena y la piedra con la provocación del necio. La palabra significa carga o peso, aquello que oprime hacia abajo. En paralelo con ''pesadez'', enfatiza cómo el peso físico no es nada comparado con la carga exasperante de lidiar con un necio. Es literatura sapiencial que emplea imágenes concretas y medibles para comunicar una realidad emocional y relacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5193', 'spa', 'Plantar vegetación, árboles o viñedos; figuradamente, establecer a un pueblo en una tierra o fijar algo en su lugar.', 'Plantar vegetación, árboles o viñedos; figuradamente, establecer a un pueblo en una tierra o fijar algo en su lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5194', 'spa', 'נֶטַע — plantación, plantío, planta; lo que ha sido plantado y cultivado intencionalmente', 'Este sustantivo designa una plantación, un plantío o una planta cultivada: algo plantado deliberadamente y no surgido de forma silvestre. Aparece en literatura profética y sapiencial, a menudo con significado metafórico. Isaías lo emplea figuradamente para referirse a Israel como plantío de Dios y también para prácticas idolátricas. Job lo usa en un símil sobre la renovación humana. El concepto subraya el cultivo intencional y la relación entre quien planta y lo plantado, lo cual lo hace especialmente apto para metáforas teológicas sobre el pueblo de Dios o las devociones religiosas humanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5195', 'spa', 'plantas, brotes — plantas jóvenes o plantíos, usado figuradamente para jóvenes vigorosos', 'Este sustantivo aparece en la oración del Salmo 144 por la bendición nacional, donde los hijos son comparados con plantas que han crecido altas en su juventud. La metáfora evoca una agricultura saludable: plantas jóvenes robustas y bien establecidas que representan la fuerza de la nueva generación. El antiguo Israel era agrícola, por lo que esta imaginería expresaba naturalmente las esperanzas de prosperidad familiar y nacional. Hijos vigorosos como plantas florecientes, hijas fructíferas como columnas labradas de palacio: señales de bendición divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5196', 'spa', 'Netaim — una localidad en Judá donde vivían y trabajaban alfareros reales', 'Netaim aparece únicamente en Crónicas, identificada como un lugar donde alfareros vivían y trabajaban para el rey. El nombre probablemente significa ''plantíos'' o ''lugares plantados'', posiblemente indicando jardines o campos cultivados. Estos eran artesanos reales dedicados a producir cerámica, una industria esencial en el mundo antiguo. La localidad es por lo demás desconocida, preservada solo en esta breve nota genealógica sobre asentamientos de la tribu de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5197', 'spa', 'Gotear o destilar (de un líquido); figuradamente, profetizar o predicar (dejando fluir las palabras)', 'Gotear o destilar (de un líquido); figuradamente, profetizar o predicar (dejando fluir las palabras)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5200', 'spa', 'Netofatita — gentilicio de Netofá, aldea cercana a Belén; hogar de guerreros de David y cantores levitas', 'El gentilicio נְטוֹפָתִי (Netophathi) identifica a una persona originaria de Netofá, aldea cercana a Belén. Los guerreros de élite de David, Maharai y Heleb, llevan esta designación (2 Sam 23:28-29; 1 Cr 11:30; 27:13, 15). Tras la caída de Jerusalén, Seraías el netofatita se une a Gedalías (2 Re 25:23; Jer 40:8). En los registros genealógicos, los netofatitas figuran entre los clanes de Judá (1 Cr 2:54) y entre los cantores levitas que se asentaron cerca de Netofá después del exilio (1 Cr 9:16; Neh 12:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5201', 'spa', 'Guardar, custodiar; vigilar una viña o mantener la ira — preservar lo encomendado o albergar lo que debería soltarse.', 'Verbo poético con dos aplicaciones llamativamente distintas del mismo sentido nuclear ''guardar''. En el Cantar de los Cantares, la amada lamenta que mientras la obligaron a ''guardar'' las viñas ajenas, la suya propia descuidó (1:6) — una imagen tierna de fidelidad custodial. Sin embargo, en textos proféticos y legales, la misma palabra describe retener la ira: Nahúm 1:2 declara que el SEÑOR ''guarda ira'' contra sus enemigos, y Levítico 19:18 prohíbe guardar rencor. La tensión entre estos sentidos revela un vocablo sobre la tenacidad del aferrarse — ya sea que ese agarre constituya cuidado virtuoso o resentimiento destructivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5203', 'spa', 'Dejar, abandonar, desamparar; también esparcir, dispersar, arrojar o soltar en juicio', 'Dejar, abandonar, desamparar; también esparcir, dispersar, arrojar o soltar en juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5207', 'spa', 'Apaciguante, agradable — término sacrificial para el aroma aceptable a Dios (רֵיחַ נִיחוֹחַ)', 'Apaciguante, agradable — término sacrificial para el aroma aceptable a Dios (רֵיחַ נִיחוֹחַ)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5209', 'spa', 'Descendencia, progenie o posteridad (en paralelo con ''nietos'')', 'Este término para descendientes aparece siempre en paralelo con נֶכֶד (nietos/posteridad), formando un merismo que abarca el linaje completo. Abraham hace jurar a Abimelec que no tratará con falsedad «ni a mí, ni a mi descendencia, ni a mi posteridad». Job describe al malvado como alguien sin «descendencia ni posteridad entre su pueblo». Isaías profetiza que Babilonia será destruida sin dejar «ni nombre ni resto, ni descendencia ni posteridad». La pareja de términos enfatiza la extinción o preservación generacional total: ningún sobreviviente en generación alguna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5210', 'spa', 'Nínive — antigua capital de Asiria junto al Tigris, lugar de la misión profética de Jonás y símbolo de poder imperial bajo juicio divino', 'Nínive — antigua capital de Asiria junto al Tigris, lugar de la misión profética de Jonás y símbolo de poder imperial bajo juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5215', 'spa', 'נִיר — barbecho, tierra sin labrar; terreno que necesita ser roturado para el cultivo', 'Este sustantivo designa el barbecho o tierra sin labrar: suelo que ha quedado en desuso y que requiere ser roturado antes de volverse productivo. Oseas y Jeremías lo emplean metafóricamente para la renovación espiritual: así como la tierra endurecida del barbecho debe ser arada y removida antes de la siembra, los corazones endurecidos necesitan un arrepentimiento radical para poder recibir la palabra de Dios. Proverbios lo usa en sentido literal para describir tierras de personas pobres que podrían ser productivas si se trabajaran debidamente. La imagen enfatiza tanto el potencial del terreno sin cultivar como el arduo trabajo necesario para hacerlo fructificar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5216a', 'spa', 'Lámpara; una lámpara de aceite literal (especialmente del tabernáculo/templo) o una lámpara figurativa que simboliza vida, dinastía o guía divina', 'Lámpara; una lámpara de aceite literal (especialmente del tabernáculo/templo) o una lámpara figurativa que simboliza vida, dinastía o guía divina');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5216b', 'spa', 'נִיר — lámpara, luz; símbolo de continuidad dinástica o bendición vivificante', 'Este sustantivo significa lámpara o luz, y se emplea exclusivamente en contextos figurados para simbolizar la sucesión dinástica continua, la vida o la bendición. La imagen se basa en la práctica antigua del hogar donde una lámpara encendida permanentemente representaba la continuidad de la vida familiar y la prosperidad. En el contexto del pacto davídico, Dios promete mantener «una lámpara» para David, asegurando la permanencia de su dinastía en el trono. La metáfora de la lámpara aparece también en la literatura sapiencial como símbolo de vida y prosperidad. Una lámpara encendida representa presencia, vitalidad y esperanza; su extinción significa muerte o fin de la dinastía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5218b', 'spa', 'Quebrantado, abatido o herido (especialmente del espíritu)', 'Este adjetivo describe una condición de quebranto o abatimiento, usado exclusivamente en Proverbios para referirse a un «espíritu quebrantado». El término aparece en sentencias sapienciales que contrastan los efectos de la alegría y la tristeza en el ser interior. Un corazón alegre hermosea el rostro, pero «el espíritu quebrantado seca los huesos». Un corazón gozoso es buena medicina, pero «el espíritu quebrantado seca los huesos». Proverbios pregunta: «el espíritu quebrantado, ¿quién lo soportará?», reconociendo el peso insoportable de la devastación interior. La imagen es la de alguien aplastado y destrozado por dentro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5220', 'spa', 'Posteridad, nietos o descendientes de generaciones posteriores (en paralelo con ''descendencia'')', 'Este término designa nietos o descendientes de generaciones posteriores, y aparece siempre emparejado con נִין (descendencia) para abarcar toda la extensión de la progenie. La combinación lingüística crea un cuadro completo: los hijos inmediatos y los hijos de sus hijos. El juramento de Abraham con Abimelec cubre «descendencia y posteridad», es decir, todas las generaciones futuras. La descripción de Job sobre el malvado sin «descendencia ni posteridad» implica extinción generacional total. La profecía de Isaías contra Babilonia promete cortar «descendencia y posteridad», sin sobreviviente en generación alguna. El término enfatiza la continuidad más allá de la generación inmediata.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5221', 'spa', 'Golpear, herir, matar; derrotar; azotar, infligir plaga; batir (palmas) — verbo de impacto violento en diversos grados.', 'Este verbo de impacto violento aparece 502 veces, nunca en Qal sino casi exclusivamente en Hifil causativo (''hacer que sea golpeado''), con raras formas pasivas Nifal, Pual y Hofal. El núcleo semántico es el golpe físico, pero el contexto determina si se trata de un golpe militar (herir enemigos en batalla, 362x), disciplinario (azotar a una persona, 35x), letal (dar muerte, 21x) o divino (afligir con plaga, 19x). Un uso pintoresco: batir palmas (4x). La evidencia multilingüe muestra que el español distingue golpear, herir, matar, el coreano separa 치다 (golpear), 때리다 (azotar) y 죽이다 (matar), mientras que el hebreo emplea un solo Hifil para todo, dejando que el contexto y el complemento regulen la intensidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5223', 'spa', 'herido, golpeado; física o espiritualmente quebrantado, lisiado o contrito', 'Este adjetivo describe a quien ha sido golpeado o quebrantado de manera profunda, ya sea en el cuerpo o en el espíritu. La raíz hebrea transmite la idea de un golpe que deja una marca duradera. En 2 Samuel se aplica a un hombre lisiado de ambos pies por una lesión sufrida en la infancia, mientras que Isaías lo emplea metafóricamente para referirse al «contrito de espíritu», aquel que está interiormente quebrantado por el reconocimiento de su pecado. El concepto subyacente une la discapacidad física y la humildad espiritual bajo la imagen de haber sido fundamentalmente herido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5224', 'spa', 'Necao II, faraón egipcio contemporáneo de Josías (611-605 a.C.)', 'Este nombre propio designa al faraón egipcio Necao II, quien reinó durante los últimos años de independencia de Judá. Mató al rey Josías en Meguido cuando este intentó bloquear su marcha hacia el norte (2 Reyes 23:29). El nombre proviene del egipcio «Nkw» (Nekawō), documentado también en registros asirios como «Nikû». Las Escrituras lo identifican sistemáticamente con su título real «Faraón Necao», destacando su papel en las convulsiones geopolíticas que precedieron a la conquista babilónica de Jerusalén. Su victoria sobre Josías marcó un trágico punto de inflexión para Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5227', 'spa', 'Enfrente, frente a, delante de (espacial); en favor de; directamente hacia adelante (direccional).', 'Enfrente, frente a, delante de (espacial); en favor de; directamente hacia adelante (direccional).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5228', 'spa', 'נָכֹחַ — recto, honesto, directo; que procede con rectitud en conducta o palabra', 'Este adjetivo significa recto, honesto o directo, y describe tanto la rectitud literal (andar por un camino derecho) como la integridad figurada (palabras honestas, conducta justa). El término aparece en la literatura sapiencial y profética, donde subraya la franqueza moral en contraste con la tortuosidad y el engaño. Las palabras pueden ser «rectas» (conducen directamente a la verdad), la conducta puede ser «directa» (caminar sin desviarse), y los argumentos pueden ser «honestos» (presentados con veracidad). La imagen siempre contrasta el camino recto con las alternativas torcidas y engañosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5229', 'spa', 'נְכֹחָה — rectitud, honestidad, integridad; conducta recta y justa', 'Este sustantivo femenino designa la rectitud, la honestidad o la integridad como cualidad abstracta o como práctica concreta. Describe lo que es moralmente recto, particularmente en contextos que examinan la justicia, la veracidad y la conducta ética. Isaías lo emplea ampliamente para diagnosticar la condición moral de Israel: su incapacidad de practicar la rectitud o su rechazo abierto de ella. Amós lo usa para acusar a la élite adinerada que no sabe «practicar» la rectitud. El término enfatiza no solo la creencia correcta, sino la acción correcta: el ejercicio real de lo recto y honesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5230', 'spa', 'נָכַל — ser astuto, engañar; tramar con astucia para causar daño', 'Este verbo significa ser astuto, engañar o actuar con doblez, describiendo una astucia deliberada orientada a perjudicar o embaucar a otros. El término aparece en acadio (ser astuto), arameo y siríaco con significados similares de engaño y maquinación. El uso bíblico abarca tanto la cualidad de ser un embustero como la acción de conspirar contra otros. Los contextos incluyen conspiración traicionera (los hermanos de José), engaño enemigo (los madianitas) y culto infiel (ofrendar sacrificios defectuosos). La palabra subraya no una simple mentira, sino esquemas calculados y astutos para lograr fines egoístas o dañinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5233', 'spa', 'Riquezas, bienes, posesiones; tesoros (probablemente préstamo del acadio/arameo)', 'Término para la riqueza acumulada y las posesiones materiales, que aparece únicamente en plural (נְכָסִים). Probablemente tomado del acadio nikasu («propiedad, ganancia»), posee un matiz formal e incluso exótico en hebreo. Suele acompañar a עֹשֶׁר («riqueza») y כָּבוֹד («honor»), como en la petición de Salomón (2 Cr 1:11-12) y el lamento del Predicador por la riqueza que no se puede disfrutar (Ecl 5:19; 6:2). Josué 22:8 lo emplea para el ganado y el botín que las tribus transjordanas llevaron a casa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5234a', 'spa', 'Reconocer, discernir o admitir; también mostrar parcialidad, darse a conocer o negar el reconocimiento', 'Reconocer, discernir o admitir; también mostrar parcialidad, darse a conocer o negar el reconocimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5234b', 'spa', 'Disfrazarse, fingir identidad; tergiversar o atribuir erróneamente; entregar como ajeno; profanar, tratar como extraño.', 'Verbo denominativo construido sobre la raíz נכר (''extraño, foráneo'') que explora lo que sucede cuando lo familiar se trata como ajeno o viceversa. José ''se hizo extraño'' ante sus hermanos (Gn 42:7) y la esposa de Jeroboam se disfrazó ante el profeta (1 R 14:5-6), ambos en Hitpael reflexivo. El Piel extiende la raíz a terrenos más oscuros: enemigos que ''tergiversan'' los actos de Dios (Dt 32:27) y quienes ''profanan'' el espacio sagrado tratándolo como extranjero (Jer 19:4). Cada acepción gira en torno al mismo eje: la peligrosa confusión entre lo conocido y lo extraño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5236', 'spa', 'Extranjería; lo ajeno — usado de dioses extranjeros (אֱלֹהֵי נֵכָר) y de personas extranjeras (בֶּן־נֵכָר)', 'Extranjería; lo ajeno — usado de dioses extranjeros (אֱלֹהֵי נֵכָר) y de personas extranjeras (בֶּן־נֵכָר)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5237', 'spa', 'Extranjero, ajeno; un forastero o persona de fuera, especialmente la «mujer extranjera» de la literatura sapiencial de Proverbios', 'Extranjero, ajeno; un forastero o persona de fuera, especialmente la «mujer extranjera» de la literatura sapiencial de Proverbios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5238', 'spa', 'tesoro, casa del tesoro; la riqueza acumulada de un rey', 'Este sustantivo poco frecuente designa un depósito de tesoros o los objetos valiosos almacenados en él. Su etimología es discutida: posiblemente proviene del asirio «bīt nakamti» (casa del tesoro), de una raíz que significa «acumular». Aparece únicamente en los relatos paralelos donde Ezequías muestra a los enviados babilónicos «todo lo que había en su casa del tesoro» (2 Reyes 20:13 = Isaías 39:2). El contexto resalta la riqueza real: plata, oro, especias y aceite precioso. La forma con sufijo posesivo («su tesoro») subraya que se trata de bienes pertenecientes al monarca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5241', 'spa', 'Nemuel, nombre de dos israelitas: un hijo de Simeón y un rubenita', 'Este nombre propio identifica a dos personas distintas en las genealogías tribales de Israel. El primero es un hijo de Simeón (Números 26:12, 1 Crónicas 4:24), llamado Jemuel en listas más antiguas (Génesis 46:10, Éxodo 6:15), un patrón habitual de variación onomástica en las genealogías bíblicas. El segundo Nemuel era un rubenita, hermano de los célebres rebeldes Datán y Abiram, quienes desafiaron la autoridad de Moisés (Números 26:9). El significado del nombre es incierto, aunque la transliteración griega «Ναμουήλ» evidencia una transmisión textual estable. Se requiere contexto para distinguir a cuál Nemuel se hace referencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5243a', 'spa', 'מָלַל — marchitarse, languidecer; decaer y consumirse como la vegetación', 'Este verbo, una raíz secundaria aparentemente derivada de אֻמְלַל, significa marchitarse, desvanecerse o languidecer, describiendo el ajamiento de las plantas o el declive de las personas. La imagen siempre recurre al marchitamiento botánico aplicado a la mortalidad humana o al juicio divino. La hierba que se seca al calor se convierte en metáfora de la rápida desaparición de los impíos o de la fragilidad humana. Job lo emplea para describir tanto la brevedad de la vida como el marchitamiento de la prosperidad del malvado. El tallo Polel intensifica el proceso de deterioro. La mayoría de los estudiosos modernos leen estas formas como Qal y no como Nifal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5246', 'spa', 'Leopardo; gran felino depredador de pelaje moteado, empleado en la imagineria profetica para representar rapidez, peligro y juicio venidero.', 'El leopardo (Panthera pardus), un poderoso depredador de pelaje moteado que aparece en las Escrituras hebreas casi exclusivamente en contextos profeticos y poeticos. Su rasgo distintivo en el uso biblico son sus manchas: Jeremias 13:23 pregunta si el leopardo puede cambiarlas, proverbio sobre la imposibilidad de la transformacion moral. Oseas 13:7 lo emplea como metafora del juicio feroz de Dios, mientras que Habacuc 1:8 destaca la aterradora velocidad de la caballeria caldea comparando sus caballos con leopardos. Isaias 11:6 vislumbra la era mesianica como un tiempo en que el leopardo descansara junto al cabrito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5248', 'spa', 'Nimrod — cazador legendario y guerrero poderoso; fundador de ciudades mesopotámicas como Babel, Nínive y Cala', 'Nimrod es una de las figuras más enigmáticas de las Escrituras: un «poderoso cazador delante del SEÑOR» cuyo nombre se volvió proverbial (Gn 10:9). Como descendiente de Cam a través de Cus, fundó el reino de Sinar (Babilonia) y edificó varias ciudades importantes de Mesopotamia. La etimología exacta sigue siendo incierta, aunque algunos intérpretes antiguos la vincularon con la rebelión. La tradición posterior, en Miqueas 5:6, usa «tierra de Nimrod» como sinónimo de Asiria, mostrando cómo su legado se convirtió en emblema del poder imperial mesopotámico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5250', 'spa', 'Nimsí — abuelo (o ancestro) del rey Jehú de Israel', 'Nombre del abuelo (o ancestro más lejano) de Jehú, usado invariablemente en la fórmula patronímica «Jehú hijo de Nimsí». Esta expresión identificativa aparece en los relatos del encargo de Elías de ungir a Jehú (1 R 19:16), la revuelta y unción de Jehú (2 R 9:2, 14, 20) y el relato del Cronista sobre la muerte de Ocozías (2 Cr 22:7). La Septuaginta lo transcribe como Namesthei o Namessei. El nombre podría derivar de la raíz מ-שׁ-ה («sacar, extraer»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5251', 'spa', 'Bandera, estandarte o enseña alzada como punto de reunión; asta o mástil; señal de advertencia', 'Bandera, estandarte o enseña alzada como punto de reunión; asta o mástil; señal de advertencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5253', 'spa', 'Retroceder, remover un lindero, retirarse o ser rechazado; usado para la remoción ilícita de linderos, la apostasía y la derrota de la justicia.', 'Verbo cuyo corazón semántico es el desplazamiento no autorizado — mover algo o a alguien del lugar que legítimamente le corresponde. Su uso bíblico más distintivo es la prohibición en Hifil de mover la piedra limítrofe del prójimo (Dt 19:14, 27:17; Pr 22:28, 23:10), un delito que atentaba contra los fundamentos mismos de la teología israelita de la tierra. Las formas Nifal describen retroceso y retirada, aplicadas con fuerza a la justicia y la verdad que ''retroceden'' en la acusación judicial de Isaías (Is 59:13-14). Oseas compara a los príncipes de Judá con quienes mueven linderos (Os 5:10), fusionando las dimensiones concreta y pactual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5254', 'spa', 'Probar, poner a prueba o intentar; ya sea Dios probando a los humanos, los humanos tentando a Dios, o intentar algo atrevido', 'Probar, poner a prueba o intentar; ya sea Dios probando a los humanos, los humanos tentando a Dios, o intentar algo atrevido');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5255', 'spa', 'נָסַח — arrancar, desarraigar o remover con violencia; extirpar por la fuerza', 'Este verbo significa arrancar o desarraigar con violencia, remover algo o a alguien por la fuerza de su lugar. La imagen central es la de una extracción violenta, como arrancar una planta de raíz o expulsar a alguien de su morada. Proverbios y Salmos lo emplean para describir el juicio divino que desarraiga a los malvados y soberbios. Deuteronomio lo usa para referirse al exilio, cuando Israel es arrancado de su tierra. El sentido bíblico se centra en la remoción forzosa, a menudo con carácter definitivo y destructivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5257b', 'spa', 'נְסִיכֵי — príncipes, caudillos; líderes tribales o regionales', 'Esta forma nominal plural designa príncipes o caudillos, líderes de grupos tribales o regionales. A diferencia del término más común para «príncipe» (נָשִׂיא), esta palabra aparece principalmente en textos poéticos y se refiere a gobernantes enemigos derrotados o soberanos extranjeros. Los contextos implican derrota militar y juicio: reyes madianitas vencidos por Israel, príncipes del norte humillados y gobernantes de Edom en los oráculos de Ezequiel. El término connota un liderazgo hereditario establecido sobre territorios definidos, particularmente de pueblos no israelitas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5258a', 'spa', 'Derramar, especialmente libaciones u ofrendas líquidas; también fundir metal; en voz pasiva, ser derramado.', 'Derramar, especialmente libaciones u ofrendas líquidas; también fundir metal; en voz pasiva, ser derramado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5262', 'spa', 'Libación u ofrenda líquida derramada en el culto; también una imagen fundida o ídolo de metal.', 'Libación u ofrenda líquida derramada en el culto; también una imagen fundida o ídolo de metal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5265', 'spa', 'Arrancar (estacas), partir, viajar; Hifil: desarraigar, cantear piedra, hacer marchar; Nifal: ser arrancado.', 'El verbo por excelencia de la peregrinación de Israel por el desierto — נסע significaba originalmente arrancar las estacas de la tienda y levantar campamento, y luego se amplió a ''partir, viajar, marchar''. Solo Números 10 lo emplea más de una docena de veces mientras cada división tribal parte en orden. La imagen concreta de arrancar estacas pervive en el Hifil ''cantear piedras'' (1 R 5:17) y ''trasplantar una vid'' (Sal 80:8). El español partieron y el francés voyagèrent captan el sentido de travesía, mientras que el coreano 뽑히다 (''ser arrancado'') conserva la imagen física pasiva. Desde la primera partida de Abram en Génesis 12:9 hasta la marcha final hacia Canaán, este verbo narra toda la peregrinación de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5267', 'spa', 'subir, ascender; préstamo arameo para movimiento ascendente', 'Este verbo arameo, incorporado al hebreo bíblico tardío, describe un movimiento hacia arriba o una elevación. En las visiones de Daniel, representa a bestias que emergen del mar y a un cuerno que surge entre otros. Esdras lo emplea para referirse a quienes suben a Jerusalén. En forma causativa (hafel: hacer subir, sacar), aparece cuando Sadrac, Mesac y Abednego son sacados de la boca del horno. La raíz aramea enfatiza la dirección y la culminación del ascenso, ya sea literal (geográfico, arquitectónico) o simbólico (surgimiento en una visión, elevación de estatus).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5270', 'spa', 'Noá — nombre propio femenino, una de las cinco hijas de Zelofehad que heredaron tierras', 'Noá es un nombre propio femenino (distinto del patriarca Noé) que lleva una de las cinco hijas de Zelofehad, de la tribu de Manasés. Estas mujeres son célebres en la legislación bíblica por sentar el precedente de que las hijas podían heredar la porción de su padre cuando no había hijos varones. Su caso aparece varias veces en Números y Josué, lo que subraya su importancia jurídica para las prácticas hereditarias israelitas. La Septuaginta traduce el nombre como Νουα. Su significado podría ser «movimiento» o «reposo», aunque su sentido exacto es incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5271a', 'spa', 'Juventud, vida temprana — el período de inmadurez o años formativos, usado tanto de personas como de naciones', 'Juventud, vida temprana — el período de inmadurez o años formativos, usado tanto de personas como de naciones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5273a', 'spa', 'Agradable, deleitoso — adjetivo poético que describe lo que produce gozo profundo o deleite estético', 'El adjetivo נָעִים (naim) expresa hermosura, agrado o deleite: la cualidad que hace algo profundamente placentero. Es una palabra eminentemente poética, que florece en Salmos y Proverbios. David es llamado el «dulce cantor de Israel» (2 Sam 23:1), y el Salmo 133:1 celebra cuán «agradable» es que los hermanos habiten en armonía. El Salterio alaba el nombre de Dios como agradable (Sal 135:3) y declara que a la diestra de Dios hay «delicias para siempre» (Sal 16:11). Proverbios lo aplica a los dichos sabios guardados en los labios (Prov 22:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5274a', 'spa', 'Cerrar con cerrojo, atrancar o asegurar; trabar una puerta firmemente para impedir la entrada o la salida.', 'Verbo que significa atrancar, echar cerrojo o cerrar con llave una puerta o portada, asegurandola contra toda entrada. En el relato de Ehud (Jue 3:23-24), este echa cerrojo a las puertas del aposento alto tras asesinar al rey Eglon, y los siervos las encuentran cerradas. En 2 Samuel 13:17-18, el criado de Amnon cierra la puerta tras Tamar despues de su violacion, detalle cruel subrayado por la accion de atrancar. Cantares 4:12 emplea el participio pasivo en sentido poetico: la amada es un jardin cerrado, imagen de pureza e inaccesibilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5275', 'spa', 'Sandalia, calzado — calzado básico de cuero que simboliza transferencia legal, valor ínfimo y disposición para el camino.', 'Sandalia, calzado — calzado básico de cuero que simboliza transferencia legal, valor ínfimo y disposición para el camino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5276', 'spa', 'Ser agradable, deleitoso o encantador; verbo estativo que describe belleza, sabor o experiencia placentera.', 'Verbo estativo en Qal que expresa la cualidad de ser agradable, placentero o deleitoso. Abarca una amplia gama de experiencias gratas: una tierra ''agradable'' en la bendición de Isacar (Gn 49:15), la dulzura incomparable del afecto de Jonatán (2 S 1:26), la suavidad de las aguas robadas (Pr 9:17) y el deleite interior cuando la sabiduría penetra en el alma (Pr 2:10). Desde el encanto estético hasta el afecto personal profundo, el verbo capta todo aquello que resulta genuinamente placentero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5278', 'spa', 'Amenidad, deleite, hermosura graciosa; también ''Gracia'' como nombre simbólico de un cayado pastoril.', 'Sustantivo delicado que capta la cualidad de deleite, belleza y favor benigno. El salmista anhela ''contemplar la נֹעַם del SEÑOR'' en su templo (Sal 27:4), y Proverbios celebra los ''caminos de amenidad'' de la sabiduría (Pr 3:17). En el Salmo 90:17 Moisés ora para que la נֹעַם de Dios repose sobre la obra de Israel. Zacarías reutiliza la palabra como nombre propio simbólico de un cayado pastoril llamado ''Gracia'', que representa el favor de Dios hacia su pueblo del pacto (Zac 11:7, 10). Cuando ese cayado se quiebra, la gracia que simbolizaba queda revocada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5279a', 'spa', 'Naamá — nombre propio femenino, hermana de Tubal-Caín y madre de Roboam', 'Naamá es un nombre propio femenino que posiblemente significa «agradable» o «hermosa», llevado por dos mujeres en las Escrituras. Primero, fue la hermana de Tubal-Caín en la genealogía antediluviana de Caín, la única mujer nombrada en esa línea aparte de Eva, lo que sugiere cierta relevancia aunque su papel no se explica. Segundo, y de forma más prominente, fue una princesa amonita que se convirtió en esposa de Salomón y madre del rey Roboam. Su origen extranjero pudo haber contribuido a las prácticas sincretistas de Salomón condenadas en Reyes. La Septuaginta emplea varias grafías griegas para sus distintas apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5281', 'spa', 'Noemí — ''mi deleite, mi dulzura''; suegra de Rut, figura central del libro de Rut', 'Noemí — ''mi deleite, mi dulzura''; suegra de Rut, figura central del libro de Rut');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5283', 'spa', 'Naamán — nombre propio que significa ''agradable''; especialmente el general arameo sanado de lepra por Eliseo', 'Naamán — nombre propio que significa ''agradable''; especialmente el general arameo sanado de lepra por Eliseo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5284', 'spa', 'el naamatita — gentilicio que designa el origen geográfico o clan de Zofar', 'Este adjetivo gentilicio designa el origen o clan de Zofar, y aparece exclusivamente como parte de la expresión «Zofar el naamatita», uno de los tres amigos de Job. El término indica una conexión con un lugar o clan llamado Naamá, aunque su ubicación exacta es incierta. No se menciona ninguna ciudad con ese nombre en la geografía bíblica cercana, lo que ha generado diversas propuestas académicas. La Septuaginta lo traduce como «el mineo» o «rey de los mineos», reflejando tradiciones interpretativas antiguas. La designación sirve principalmente para identificar y distinguir a Zofar de otros personajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5287', 'spa', 'Sacudir, arrojar; sacudir vigorosamente; ser sacudido; sacudirse, liberarse', 'Un verbo cinético de desalojo enérgico, usado desde Dios arrojando al ejército del faraón al mar hasta un insecto sacudido de un pliegue del vestido. Nehemías sacudió su manto como acto profético, advirtiendo que Dios sacudiría de igual modo a quien quebrantara su juramento. En Isaías 52:2, Sion cautiva recibe la orden de «sacudirse del polvo», un mandato de liberación. El español capta bien la gama: «arrojó» para el Piel violento y «sacúdete» para la autoliberación reflexiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5288', 'spa', 'Muchacho, joven, mozo; criado o sirviente personal sin importar la edad; en expresiones temporales ''desde la juventud''.', 'Una de las palabras semánticamente más flexibles para designar a un varón en la Biblia hebrea, נַעַר cubre todo el espectro desde un recién nacido (Moisés en la canasta, Éx 2:6) hasta un joven guerrero vigoroso, y al mismo tiempo funciona como término estándar para un criado o sirviente personal. Solo el contexto determina si se destaca la edad o el rol social. El árabe desglosa estas acepciones en صَبِيٌّ (''niño''), شَابٌّ (''joven'') y خَادِمٌ (''sirviente''), revelando distinciones que el hebreo condensa en una sola palabra. La ambigüedad es a veces deliberada: cuando Abraham lleva a su נַעַר al monte Moria (Gn 22:3), el término evoca tanto vigor juvenil como lealtad servicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5290', 'spa', 'juventud, vida temprana; vigor juvenil o el periodo inicial de la vida de una persona', 'Este raro término poético designa el estado o periodo de la juventud, paralelo al más frecuente נְעוּרִים. En Job 33:25 describe la restauración del vigor juvenil, mientras que en la locución prepositiva «desde la juventud» señala el punto de partida de una condición prolongada. El vocablo aparece en contextos que resaltan ya sea la vitalidad propia de ser joven o la duración «desde la juventud» como medida temporal de toda una vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5291', 'spa', 'Mujer joven, muchacha; frecuentemente en edad casadera o de servicio; puede designar a una criada o asistenta.', 'Mujer joven, muchacha; frecuentemente en edad casadera o de servicio; puede designar a una criada o asistenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5292b', 'spa', 'Naara, nombre propio femenino; esposa de Asjur en la genealogía de Judá', 'Este nombre propio femenino aparece exclusivamente en los registros genealógicos de los descendientes de Judá. Naara fue una de las dos esposas de Asjur, padre de Tecoa, y el texto enumera a sus hijos junto con los de su otra esposa, Hela (1 Crónicas 4:5-6). Las traducciones griegas varían considerablemente (Θοαδα, Νοορα, Νοερα), lo cual sugiere incertidumbre sobre la pronunciación o el significado del nombre. Curiosamente, este nombre es idéntico en forma al sustantivo común que significa «joven» o «muchacha», lo que pudo generar confusión entre el nombre propio y el sustantivo común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5294', 'spa', 'Nearías, nombre de dos hombres postexílicos: un descendiente de David y un líder simeonita', 'Este nombre masculino identifica a dos individuos en las genealogías de Crónicas. El primer Nearías fue un descendiente del rey David a través de la línea de Zorobabel (1 Crónicas 3:22-23), y aparece entre los descendientes reales postexílicos que ya no gobernaban pero mantenían su linaje davídico. El segundo fue un líder simeonita que participó en una campaña militar contra el remanente amalecita en Edom (1 Crónicas 4:42). El nombre parece significar «siervo de Yahvé» o «Yah ha sacudido (libre)», aunque la derivación exacta es debatida. Las traducciones griegas varían, lo que sugiere que el nombre era poco frecuente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5297', 'spa', 'Nof (Menfis); antigua capital egipcia a orillas del Nilo, mencionada frecuentemente en oráculos proféticos contra Egipto.', 'Nombre hebreo de Menfis, la antigua capital de Egipto ubicada al sur del delta del Nilo. Aparece en dos variantes — Nof y Mof — y ocupa un lugar destacado en las denuncias proféticas contra Egipto. Jeremías 2:16 advierte que «los hijos de Nof» quebraron la corona de Israel, mientras que Jeremías 44:1 y 46:14,19 se dirigen a los refugiados judíos que se establecieron allí. Isaías 19:13 declara engañados a sus príncipes, y Ezequiel 30:13 anuncia que Dios destruirá sus ídolos. La Septuaginta griega lo traduce como Memphis, conservando el egipcio Mn-nfr («belleza perdurable»).');